import json, sys, os, glob
root = sys.argv[1]; out = sys.argv[2]
os.makedirs(out, exist_ok=True)
for path in glob.glob(os.path.join(root, '**', '*.jsonl'), recursive=True):
    name = os.path.relpath(path, root).replace(os.sep, '__')
    lines = []
    tools = {}
    with open(path, encoding='utf-8', errors='replace') as f:
        for raw in f:
            try: d = json.loads(raw)
            except Exception: continue
            t = d.get('type'); ts = d.get('timestamp', '')[:19]
            msg = d.get('message') or {}
            c = msg.get('content')
            if t == 'summary':
                lines.append(f"[SUMMARY] {d.get('summary')}")
            if t not in ('user', 'assistant'): continue
            if isinstance(c, str):
                if t == 'user' and not c.startswith('<'):
                    lines.append(f"\n### USER {ts}\n{c[:3000]}")
                continue
            if not isinstance(c, list): continue
            for b in c:
                bt = b.get('type')
                if bt == 'text' and b.get('text', '').strip():
                    txt = b['text']
                    if t == 'user':
                        if txt.startswith('<system-reminder>'): continue
                        lines.append(f"\n### USER {ts}\n{txt[:3000]}")
                    else:
                        lines.append(f"\n--- ASSISTANT {ts}\n{txt[:2500]}")
                elif bt == 'tool_use':
                    n = b.get('name'); tools[n] = tools.get(n, 0) + 1
                    inp = b.get('input', {})
                    hint = inp.get('description') or inp.get('file_path') or inp.get('command') or inp.get('pattern') or ''
                    lines.append(f"  [tool {n}] {str(hint)[:160]}")
    with open(os.path.join(out, name + '.md'), 'w', encoding='utf-8') as o:
        o.write(f"# {name}\nTool counts: {tools}\n" + '\n'.join(lines))
    print(name, len(lines), os.path.getsize(os.path.join(out, name + '.md')))

