"""Deobfuscation fixes as approval-gated proposals (pure Python, no IDA, no model).

Turns Binary Triage's deterministic code signals and raw function bytes into
``ChangeManager`` proposals - nothing here writes anything:

1. **API hashing** - a comment at every resolved hash constant
   (``API hash 0x0726774C -> kernel32.dll!LoadLibraryA (ror13)``) and, where
   the resolver's result is stored to a global, a rename of that global to
   ``p_<API>``;
2. (the extra hash algorithms live in ``analysis/deobfuscation.py``);
3. **decoded strings** - a comment with each stack string / XOR-decoded string;
4. **anti-disassembly and opaque branches** - byte patches (``patch_bytes``)
   for patterns with a single meaning, all x86/x64:

   * complementary conditional jumps to the same target (``jz X / jnz X``,
     short or near) with junk bytes before ``X`` -> NOPs up to ``X``;
   * a branch that is always taken because the flags are constant
     (``xor r32,r32 ; jz``, ``stc ; jc``, ``clc ; jnc``) -> NOPs up to the
     target (forward, short) or ``jmp``;
   * a branch that is never taken (``clc ; jc``, ``stc ; jnc``) -> NOPs;
   * a short ``jmp`` over 1-4 junk bytes that start a bogus instruction
     (``E8``/``E9``/``0F``/``FF``/...) -> NOPs.

   A pattern counts only if it starts at an instruction head IDA already
   decoded, its region is at most ``MAX_PATCH_BYTES`` and strictly forward,
   and patches never overlap. Replacing such a region with NOPs keeps the
   program's behaviour (control reaches the same target with the same state).
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Dict, FrozenSet, Iterable, List, Optional, Sequence, Tuple

MAX_PATCH_BYTES = 32
MAX_PATCHES_PER_FUNCTION = 64
MAX_PATCHES = 500
MAX_COMMENT_CHARS = 300
NOP = 0x90
# First byte of a "junk" instruction placed after a short jmp to desynchronise linear disassembly.
_JUNK_STARTS: FrozenSet[int] = frozenset({0xE8, 0xE9, 0xEA, 0x9A, 0x0F, 0xFF, 0xC7, 0x81, 0x69, 0x6B, 0xC8})
# ``xor r32, r32`` / ``xor r64, r64`` (opcode 31 or 33, ModRM with reg == rm): ZF is always set.
_XOR_SELF_MODRM: FrozenSet[int] = frozenset(0xC0 | (reg << 3) | reg for reg in range(8))
_NAME_DEFAULT_PREFIXES = ("qword_", "dword_", "off_", "unk_", "byte_", "word_", "xmmword_", "stru_", "loc_", "")
_IDENT = re.compile(r"[^A-Za-z0-9_]")


@dataclass(frozen=True)
class FixProposal:
    """One proposal for ``ChangeManager.propose``; ``kind`` groups them for the summary."""

    kind: str           # "api_hash_comment" | "api_pointer_name" | "decoded_string" | "patch"
    operation: str      # add_comment | rename_global | patch_bytes
    address: int
    value: str
    reason: str
    evidence: Tuple[str, ...] = ()
    confidence: float = 0.9
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class BytePatch:
    address: int
    original: bytes
    replacement: bytes
    description: str


# ---------------------------------------------------------------------------
# 1. API hashing  /  3. decoded strings
# ---------------------------------------------------------------------------


def api_name_identifier(api: str) -> Optional[str]:
    """``kernel32.dll!LoadLibraryA`` -> ``p_LoadLibraryA`` (IDA identifier, or None)."""
    bare = api.split("!", 1)[-1]
    cleaned = _IDENT.sub("_", bare).strip("_")
    if not cleaned:
        return None
    name = "p_" + cleaned
    return name[:120]


def _printable(text: str, limit: int) -> str:
    value = "".join(ch if ch.isprintable() else "\\x{0:02x}".format(ord(ch)) for ch in text)
    return value if len(value) <= limit else value[: limit - 1] + "…"


def hash_proposals(signals: Any) -> List[FixProposal]:
    """Comments at resolved hash constants plus ``p_<API>`` renames of the pointer globals."""
    output: List[FixProposal] = []
    for function in tuple(getattr(signals, "functions", ()) or ()):
        stores = dict(getattr(function, "pointer_stores", ()) or ())
        for ea, value, algorithm, api in function.api_hashes:
            evidence = ("0x{0:X}: constant 0x{1:08X} in {2}".format(ea, value, function.name),
                        "hash algorithm {0} matched by >= 2 constants in this binary".format(algorithm))
            output.append(FixProposal(
                "api_hash_comment", "add_comment", ea,
                "API hash 0x{0:08X} -> {1} ({2})".format(value, api, algorithm),
                "Resolved API hash (deterministic: matched against the known-API catalogue)", evidence, 0.9,
            ))
            target = stores.get(ea)
            name = api_name_identifier(api)
            if target is not None and name is not None:
                output.append(FixProposal(
                    "api_pointer_name", "rename_global", target, name,
                    "Global receives the pointer resolved for {0}".format(api),
                    evidence + ("0x{0:X}: resolver result stored here".format(target),), 0.8,
                    {"api": api},
                ))
    return output


def decoded_string_proposals(signals: Any) -> List[FixProposal]:
    output: List[FixProposal] = []
    for function in tuple(getattr(signals, "functions", ()) or ()):
        for address, text, method in function.decoded_strings:
            if not text.strip():
                continue
            output.append(FixProposal(
                "decoded_string", "add_comment", address,
                'Decoded string: "{0}" [{1}]'.format(_printable(text, MAX_COMMENT_CHARS - 40), method),
                "String decoded locally ({0}) in {1}".format(method, function.name),
                ("0x{0:X}: {1}".format(address, method),), 0.85,
            ))
    return output


def is_default_name(name: Optional[str]) -> bool:
    """True for IDA's auto names (``qword_1400…``), i.e. a rename loses nothing the analyst chose."""
    if not name:
        return True
    return any(name.startswith(prefix) for prefix in _NAME_DEFAULT_PREFIXES if prefix) and bool(re.search(r"_[0-9A-Fa-f]+$", name))


def merge_comment(existing: Optional[str], new: str) -> Optional[str]:
    """Comment value that keeps the analyst's text; ``None`` when ``new`` is already there."""
    current = (existing or "").strip()
    if new in current:
        return None
    return (current + "\n" + new) if current else new


# ---------------------------------------------------------------------------
# 4. Anti-disassembly / opaque-branch patches
# ---------------------------------------------------------------------------


def _s8(value: int) -> int:
    return value - 0x100 if value >= 0x80 else value


def _s32(data: bytes) -> int:
    return int.from_bytes(data, "little", signed=True)


def _nop_to(data: bytes, start: int, end: int, base: int, description: str) -> Optional[BytePatch]:
    if not 0 < end - start <= MAX_PATCH_BYTES or end > len(data):
        return None
    return BytePatch(base + start, bytes(data[start:end]), bytes([NOP]) * (end - start), description)


def _short_jcc_target(data: bytes, offset: int) -> Optional[int]:
    if offset + 2 <= len(data) and 0x70 <= data[offset] <= 0x7F:
        return offset + 2 + _s8(data[offset + 1])
    return None


def _match_at(data: bytes, i: int, base: int, heads: FrozenSet[int] = frozenset()) -> Optional[BytePatch]:
    size = len(data)
    first = data[i]
    # (a) complementary short jcc pair to one target: 7x rr 7(x^1) rr'
    if 0x70 <= first <= 0x7F and i + 4 <= size and data[i + 2] == first ^ 1:
        target = _short_jcc_target(data, i)
        if target is not None and target == _short_jcc_target(data, i + 2) and target > i + 4:
            return _nop_to(data, i, target, base, "complementary jumps to the same target (anti-disassembly)")
    # (b) complementary near jcc pair: 0F 8x rel32 0F 8(x^1) rel32
    if first == 0x0F and i + 12 <= size and 0x80 <= data[i + 1] <= 0x8F and data[i + 6] == 0x0F and data[i + 7] == data[i + 1] ^ 1:
        target = i + 6 + _s32(data[i + 2:i + 6])
        if target == i + 12 + _s32(data[i + 8:i + 12]) and target > i + 12:
            return _nop_to(data, i, target, base, "complementary near jumps to the same target (anti-disassembly)")
    # (c) constant flags: [REX] xor r,r ; jz  /  stc ; jc  /  clc ; jnc  (always taken)
    #     clc ; jc  /  stc ; jnc  (never taken)
    j = None
    always: Optional[bool] = None
    what = ""
    rex = 1 if first in (0x48, 0x40, 0x49, 0x4C, 0x4D) and i + 1 < size else 0
    op = data[i + rex] if i + rex < size else None
    if op in (0x31, 0x33) and i + rex + 1 < size and data[i + rex + 1] in _XOR_SELF_MODRM and rex in (0, 1):
        j, what = i + rex + 2, "xor reg,reg"
        if j + 2 <= size and data[j] == 0x74:
            always = True
        elif j + 2 <= size and data[j] == 0x75:
            always = False
    elif first in (0xF8, 0xF9) and i + 3 <= size:
        j, what = i + 1, "stc" if first == 0xF9 else "clc"
        if data[j] == 0x72:      # jc
            always = first == 0xF9
        elif data[j] == 0x73:    # jnc
            always = first == 0xF8
    if j is not None and always is not None and j + 2 <= size:
        target = j + 2 + _s8(data[j + 1])
        mnemonic = {0x72: "jc", 0x73: "jnc", 0x74: "jz", 0x75: "jnz"}[data[j]]
        if always:
            if j + 2 < target <= j + 2 + MAX_PATCH_BYTES:
                return _nop_to(data, j, target, base, "branch always taken ({0} ; {1}) over junk".format(what, mnemonic))
            if target != j + 2:
                return BytePatch(base + j, bytes(data[j:j + 2]), bytes([0xEB, data[j + 1]]),
                                 "branch always taken ({0} ; {1}) -> jmp".format(what, mnemonic))
        else:
            return BytePatch(base + j, bytes(data[j:j + 2]), bytes([NOP, NOP]),
                             "branch never taken ({0} ; {1}) -> nop".format(what, mnemonic))
    # (d) short jmp over 1-4 junk bytes that begin a bogus instruction. A compiler's short jmp
    #     lands on an instruction IDA decoded; this trick lands inside a mis-decoded one, so the
    #     target must NOT be an existing head.
    if first == 0xEB and i + 2 < size and 1 <= data[i + 1] <= 4 and data[i + 2] in _JUNK_STARTS \
            and (base + i + 2 + data[i + 1]) not in heads:
        return _nop_to(data, i, i + 2 + data[i + 1], base, "jmp over junk byte(s) (anti-disassembly)")
    return None


def find_byte_patches(base: int, data: bytes, heads: Iterable[int], limit: int = MAX_PATCHES_PER_FUNCTION) -> List[BytePatch]:
    """Patches for the patterns above, starting only at IDA instruction heads, never overlapping."""
    blob = bytes(data)
    head_set = frozenset(heads)
    starts = sorted(head - base for head in head_set if 0 <= head - base < len(blob))
    patches: List[BytePatch] = []
    covered_until = -1
    for offset in starts:
        if offset < covered_until:
            continue
        patch = _match_at(blob, offset, base, head_set)
        if patch is None:
            continue
        end = patch.address - base + len(patch.original)
        if patch.address - base < covered_until:
            continue
        patches.append(patch)
        covered_until = end
        if len(patches) >= limit:
            break
    return patches


def patch_proposals(function_name: str, patches: Sequence[BytePatch]) -> List[FixProposal]:
    output: List[FixProposal] = []
    for patch in patches:
        output.append(FixProposal(
            "patch", "patch_bytes", patch.address, patch.replacement.hex(),
            "{0} in {1}".format(patch.description, function_name),
            ("0x{0:X}: {1} -> {2}".format(patch.address, patch.original.hex(" "), patch.replacement.hex(" ")),),
            0.85,
            {"length": len(patch.original), "description": patch.description},
        ))
    return output


__all__ = [
    "BytePatch", "FixProposal", "MAX_PATCHES", "MAX_PATCH_BYTES", "api_name_identifier", "decoded_string_proposals",
    "find_byte_patches", "hash_proposals", "is_default_name", "merge_comment", "patch_proposals",
]

            taken[wanted] = True
    return comments, names, taken


FULL_SCAN_FUNCTIONS = 20000
FULL_SCAN_INSTRUCTIONS = 4_000_000


def collect_full_code_signals(modules: IdaModules, functions: Sequence[Tuple[int, str]]) -> CodeSignals:
    """Deobfuscate: code signals over *every* given (author) function, with whole-binary limits.

    Data ranges come from the IDB's non-executable segments. IDA thread (MFF_READ).
    """
    ranges: List[Tuple[int, int]] = []
    try:
        import ida_segment
        segment = ida_segment.get_first_seg()
        while segment is not None:
            if not (int(segment.perm) & 1) and segment.end_ea > segment.start_ea:  # SEGPERM_EXEC = 1
                ranges.append((int(segment.start_ea), int(segment.end_ea)))
            segment = ida_segment.get_next_seg(segment.start_ea)
    except (ImportError, *_IDA_ERRORS):
        pass

    def is_data(address: int) -> bool:
        return any(start <= address < end for start, end in ranges)

    return collect_code_signals(modules, functions, ranges, is_data, max_instructions=4000,
                                max_functions=FULL_SCAN_FUNCTIONS, max_total_instructions=FULL_SCAN_INSTRUCTIONS)


def collect_code_signals(
    modules: IdaModules,
    functions: Sequence[Tuple[int, str]],
    data_ranges: Sequence[Tuple[int, int]],
    is_data_address: Callable[[int], bool],
    max_instructions: int = 2000,
    max_functions: int = 0,
    max_total_instructions: int = 0,
) -> CodeSignals:
    """Disassemble the given (author) functions, find crypto tables, build ``CodeSignals``.

    Triage uses the bounded defaults; Deobfuscate passes larger limits for a whole-binary scan.
    """
    max_functions = max_functions or MAX_SCAN_FUNCTIONS
    max_total_instructions = max_total_instructions or MAX_TOTAL_INSTRUCTIONS
    reader = getattr(modules.bytes, "get_bytes", None) if modules.bytes is not None else None

    def read(address: int, size: int) -> Optional[bytes]:
        if not callable(reader):
            return None
        try:
            value = reader(address, size)
        except _IDA_ERRORS:
            return None
        return bytes(value) if value else None

    def function_of(address: int) -> Optional[int]:
        try:
            function = modules.funcs.get_func(address)
        except _IDA_ERRORS:
            return None
        return int(function.start_ea) if function is not None else None

    batch = []
    total = 0
    for address, name in list(functions)[:max_functions]:
        instructions, memory = _function_instructions(modules, address, max_instructions)
        total += len(instructions)
        batch.append((address, name, instructions, memory))
        if total >= max_total_instructions:
            break
    def references_to(address: int) -> Tuple[int, ...]:
        """Functions whose code references ``address`` (hash-table entries are read by a resolver loop)."""
        if modules.idautils is None:
            return ()
        owners: List[int] = []
        try:
            for xref in modules.idautils.XrefsTo(address, 0):
                function = function_of(int(xref.frm))

"""Optional family rule pack: scan the sample with community YARA rules (e.g. Malpedia).

**Optional by design.** When ``yara64.exe`` or the rule files are missing, the
scan is skipped with a one-line note and every other part of Binary Triage,
the Report and the YARA tab works exactly as before.

Rules are looked up in ``<plugin>/bin/rules/*.yar`` plus an optional folder or
file from Settings (``yara_rules_path``). The bundled pack is Malpedia's
TLP:WHITE Windows set (one or more rules per family, written from the family's
own code); each match names the family and, where IDA can map the matched file
offsets, the functions that hold the family-specific code.

The sample is never executed: ``yara64.exe`` only reads it as a file.
"""

from __future__ import annotations

import re
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Dict, List, Optional, Sequence, Tuple

from ida_ai_malware_analyst_plugin.core.yara_tool import _run, _same_file, is_yara_executable

SCAN_TIMEOUT_SECONDS = 120.0
MAX_OFFSETS_PER_RULE = 12
# Families that are offensive tools / frameworks rather than malware (verdict: Hacktool).
HACKTOOL_FAMILIES = frozenset({
    "cobalt_strike", "metasploit", "meterpreter", "mimikatz", "sliver", "havoc", "brute_ratel_c4", "empire_downloader",
    "powersploit", "covenant", "merlin", "poshc2", "lazagne", "rubeus", "sharphound", "bloodhound", "nighthawk",
    "mythic", "koadic", "pupy", "quasar_rat_tool",
})

_RULE_LINE_RE = re.compile(r"^(?P<rule>[A-Za-z_][A-Za-z0-9_]*)\s+(?:\[(?P<meta>.*)\]\s+)?(?P<file>.+)$")
_OFFSET_LINE_RE = re.compile(r"^0x(?P<offset>[0-9a-fA-F]+):(?P<ident>\$[A-Za-z0-9_]*):")
_META_RE = re.compile(r'(\w+)="((?:[^"\\]|\\.)*)"')


@dataclass(frozen=True)
class RuleHit:
    rule: str
    family: str          # "remcos" (from win_remcos_auto / win_remcos_w0)
    display: str         # "Remcos"
    auto: bool           # Malpedia YARA-Signator auto-generated code rule
    hacktool: bool
    reference: str
    author: str
    offsets: Tuple[int, ...]                       # file offsets of matched strings / byte patterns
    functions: Tuple[Tuple[int, str], ...] = ()    # (address, name) the offsets map to (filled on the IDA thread)


@dataclass(frozen=True)
class RulePackScan:
    hits: Tuple[RuleHit, ...]
    note: str            # one line for the Triage tab (also when skipped)
    rule_files: int = 0


def rule_files(plugin_root: Optional[Path], configured: str = "") -> Tuple[Path, ...]:
    found: List[Path] = []
    text = (configured or "").strip().strip('"')
    sources = [Path(text)] if text else []
    if plugin_root is not None:
        sources.append(Path(plugin_root) / "bin" / "rules")
    for source in sources:
        try:
            if source.is_file() and source.suffix.lower() in (".yar", ".yara"):
                found.append(source)
            elif source.is_dir():
                found.extend(sorted(p for p in source.iterdir() if p.is_file() and p.suffix.lower() in (".yar", ".yara")))
        except OSError:
            continue
    return tuple(dict.fromkeys(found))


def disabled_names(plugin_root: Optional[Path], configured: str = "") -> frozenset:
    """Rule or family names from ``disabled.txt`` next to the rules (bin/rules and the Settings folder)."""
    names = set()
    folders = []
    if plugin_root is not None:
        folders.append(Path(plugin_root) / "bin" / "rules")
    text = (configured or "").strip().strip('"')
    if text:
        folders.append(Path(text) if Path(text).is_dir() else Path(text).parent)
    for folder in folders:
        try:
            lines = (folder / "disabled.txt").read_text(encoding="utf-8").splitlines()
        except OSError:
            continue
        for line in lines:
            name = line.split("#", 1)[0].strip().lower()
            if name:
                names.add(name)
    return frozenset(names)


def without_disabled(result: "RulePackScan", disabled: frozenset) -> "RulePackScan":
    if not disabled or not result.hits:
        return result
    kept = tuple(hit for hit in result.hits if hit.rule.lower() not in disabled and hit.family.lower() not in disabled)
    removed = len(result.hits) - len(kept)
    note = result.note + ("; {0} match(es) ignored (disabled.txt)".format(removed) if removed else "")
    return RulePackScan(kept, note, result.rule_files)


def _family_of(rule: str) -> Tuple[str, bool]:
    name = rule[4:] if rule.lower().startswith("win_") else rule
    auto = name.lower().endswith("_auto")
    name = re.sub(r"(_auto|_w\d+)$", "", name, flags=re.I)
    return name.lower(), auto


def _display(family: str) -> str:
    return " ".join(part.upper() if len(part) <= 3 and part.isalpha() and part not in ("rat",) else part.capitalize()
                    for part in family.split("_")).replace("Rat", "RAT")


def parse_output(text: str) -> Tuple[RuleHit, ...]:
    hits: List[RuleHit] = []
    current: Optional[Dict[str, object]] = None

    def flush() -> None:
        if current is None:
            return
        family, auto = _family_of(str(current["rule"]))
        meta = current["meta"]
        hits.append(RuleHit(
            rule=str(current["rule"]), family=family, display=_display(family), auto=auto,
            hacktool=family in HACKTOOL_FAMILIES,
            reference=str(meta.get("malpedia_reference", meta.get("reference", ""))),  # type: ignore[union-attr]
            author=str(meta.get("author", "")),  # type: ignore[union-attr]
            offsets=tuple(current["offsets"])[:MAX_OFFSETS_PER_RULE],  # type: ignore[arg-type]
        ))

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        offset = _OFFSET_LINE_RE.match(line)
        if offset and current is not None:
            value = int(offset.group("offset"), 16)
            if value not in current["offsets"]:  # type: ignore[operator]
                current["offsets"].append(value)  # type: ignore[union-attr]
            continue
        match = _RULE_LINE_RE.match(line)
        if match:
            flush()
            current = {"rule": match.group("rule"), "meta": dict(_META_RE.findall(match.group("meta") or "")), "offsets": []}
    flush()
    # One hit per family (the curated rule wins over the auto-generated one).
    best: Dict[str, RuleHit] = {}
    for hit in hits:
        kept = best.get(hit.family)
        if kept is None or (kept.auto and not hit.auto):
            best[hit.family] = hit if kept is None else RuleHit(**{**hit.__dict__, "offsets": tuple(dict.fromkeys(hit.offsets + kept.offsets))[:MAX_OFFSETS_PER_RULE]})
    return tuple(sorted(best.values(), key=lambda item: (item.auto, item.family)))


def scan(executable: Optional[Path], files: Sequence[Path], sample_path: Optional[str],
         timeout: float = SCAN_TIMEOUT_SECONDS) -> RulePackScan:
    """Run the rule pack over the sample. Never raises; a skipped scan explains itself in ``note``."""
    if not files:
        return RulePackScan((), "family rule pack not installed (bin/rules/*.yar) - skipped")
    if executable is None:
        return RulePackScan((), "family rule pack skipped: yara64.exe not found (set its path in Settings)", len(files))
    executable = Path(executable)
    if not sample_path or not Path(sample_path).is_file():
        return RulePackScan((), "family rule pack skipped: the input file is not on disk", len(files))
    if not is_yara_executable(executable) or _same_file(executable, Path(sample_path)):
        return RulePackScan((), "family rule pack skipped: {0} is not a YARA executable".format(executable.name), len(files))
    output: List[str] = []
    errors: List[str] = []
    for rule_file in files:
        try:
            code, out, err = _run([str(executable), "-w", "-m", "-s", str(rule_file), str(sample_path)], timeout)
        except subprocess.TimeoutExpired:
            errors.append("{0}: timed out".format(rule_file.name))
            continue
        except (OSError, subprocess.SubprocessError) as exc:
            errors.append("{0}: {1}".format(rule_file.name, exc))
            continue
        if code != 0:
            errors.append("{0}: {1}".format(rule_file.name, (err.strip() or "exit {0}".format(code)).splitlines()[0][:160]))
            continue
        output.append(out)
    hits = parse_output("\n".join(output))
    note = "family rule pack: {0} rule file(s) scanned, {1} family match(es){2}".format(
        len(files), len(hits), "; errors: " + "; ".join(errors[:3]) if errors else "")
    return RulePackScan(hits, note, len(files))


def with_functions(result: RulePackScan, locate: Callable[[int], Optional[Tuple[int, str]]]) -> RulePackScan:
    """Map each hit's file offsets to IDA functions (``locate`` runs on the IDA thread)."""
    hits = []
    for hit in result.hits:
        functions: List[Tuple[int, str]] = []
        for offset in hit.offsets:
            try:
                found = locate(offset)
            except Exception:
                found = None
            if found and found not in functions:
                functions.append(found)
        hits.append(RuleHit(**{**hit.__dict__, "functions": tuple(functions[:6])}))
    return RulePackScan(tuple(hits), result.note, result.rule_files)


def describe(hit: RuleHit) -> str:
    where = ", ".join("{0} (0x{1:X})".format(name, address) for address, name in hit.functions[:3])
    kind = "auto-generated code rule" if hit.auto else "curated rule"
    return "{0}: Malpedia {1} {2}{3}".format(hit.display, kind, hit.rule, " - family code in " + where if where else "")

"""Optional ``yara64.exe`` support: find it, compile a rule, scan the sample.

YARA is never required. When no executable is found, the rule is still built
and shown as "not verified"; nothing else in the plugin changes. Lookup order:

1. the path set in Settings (``yara_path``), a file or a folder;
2. ``<plugin>/bin/yara64.exe`` (or ``yara.exe``);
3. ``yara64`` / ``yara`` on ``PATH``.

The executable is run with a timeout, without a console window, on a temporary
copy of the rule. It only reads the rule and the sample.

**The sample is never executed.** Only a file named ``yara*`` is ever started,
never the sample itself (even if a misconfigured path points at it); the sample
is passed to YARA purely as a file to scan.
"""

from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Optional, Tuple

EXECUTABLE_NAMES = ("yara64.exe", "yara.exe", "yara64", "yara")
RUN_TIMEOUT_SECONDS = 60.0
MAX_OUTPUT_CHARS = 20000


@dataclass(frozen=True)
class YaraRun:
    status: str          # verified / compiled / no_match / compile_error / not_verified
    detail: str
    matched_identifiers: Tuple[str, ...] = ()
    executable: str = ""


def is_yara_executable(path: Path) -> bool:
    """Only YARA binaries may be started: the file name must be ``yara``, ``yara64`` (``.exe``)."""
    return path.name.lower() in EXECUTABLE_NAMES


def _same_file(left: Path, right: Path) -> bool:
    try:
        return left.resolve() == right.resolve() or (left.exists() and right.exists() and os.path.samefile(left, right))
    except OSError:
        return False


def find_yara(configured: str = "", plugin_root: Optional[Path] = None) -> Optional[Path]:
    """Path of a usable YARA executable, or ``None`` (anything not named ``yara*`` is ignored)."""
    candidates = []
    text = (configured or "").strip().strip('"')
    if text:
        path = Path(os.path.expandvars(os.path.expanduser(text)))
        candidates.extend([path] if path.suffix else [path / name for name in EXECUTABLE_NAMES])
        if path.is_dir():
            candidates.extend(path / name for name in EXECUTABLE_NAMES)
    if plugin_root is not None:
        candidates.extend(Path(plugin_root) / "bin" / name for name in EXECUTABLE_NAMES[:2])
    for candidate in candidates:
        try:
            if is_yara_executable(candidate) and candidate.is_file():
                return candidate
        except OSError:
            continue
    for name in ("yara64", "yara"):
        found = shutil.which(name)
        if found and is_yara_executable(Path(found)):
            return Path(found)
    return None


def _run(command, timeout: float) -> Tuple[int, str, str]:
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
    completed = subprocess.run(  # noqa: S603 - fixed argv, no shell
        command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        timeout=timeout, creationflags=flags, check=False,
    )
    decode = lambda raw: (raw or b"").decode("utf-8", "replace")[:MAX_OUTPUT_CHARS]  # noqa: E731
    return completed.returncode, decode(completed.stdout), decode(completed.stderr)


def yara_version(executable: Path) -> str:
    try:
        code, out, _err = _run([str(executable), "--version"], 15.0)
    except (OSError, subprocess.SubprocessError):
        return ""
    return out.strip().splitlines()[0] if code == 0 and out.strip() else ""


def verify_rule(executable: Optional[Path], rule_text: str, rule_name: str, sample_path: Optional[str],
                timeout: float = RUN_TIMEOUT_SECONDS) -> YaraRun:
    """Compile ``rule_text`` and scan the sample (or an empty file when the sample is missing)."""
    if executable is None:
        return YaraRun("not_verified", "yara64.exe not found - rule not compiled or tested (set its path in Settings)")
    executable = Path(executable)
    if not is_yara_executable(executable) or (sample_path and _same_file(executable, Path(sample_path))):
        # Defence in depth: never start anything but YARA, and never the sample.
        return YaraRun("not_verified", "refused to run {0}: not a YARA executable".format(executable.name))
    workdir = tempfile.mkdtemp(prefix="ida_ai_yara_")
    try:
        rule_file = Path(workdir) / "rule.yar"
        rule_file.write_text(rule_text, encoding="utf-8")
        sample = Path(sample_path) if sample_path else None
        have_sample = sample is not None and sample.is_file()
        target = sample if have_sample else Path(workdir) / "empty.bin"
        if not have_sample:
            target.write_bytes(b"")
        try:
            code, out, err = _run([str(executable), "-s", "-w", str(rule_file), str(target)], timeout)
        except subprocess.TimeoutExpired:
            return YaraRun("not_verified", "yara64.exe timed out after {0:g} s".format(timeout), executable=str(executable))
        except (OSError, subprocess.SubprocessError) as exc:
            return YaraRun("not_verified", "yara64.exe could not run: {0}".format(exc), executable=str(executable))
        if code != 0:
            message = (err.strip() or out.strip() or "exit code {0}".format(code)).splitlines()[0]
            return YaraRun("compile_error", message.replace(str(rule_file), "rule.yar")[:300], executable=str(executable))
        matched = False
        identifiers = []
        for line in out.splitlines():
            stripped = line.strip()
            if stripped.startswith(rule_name + " ") or stripped == rule_name:
                matched = True
            elif stripped.startswith("0x") and ":$" in stripped:
                identifiers.append(stripped.split(":", 2)[1])
        found = tuple(dict.fromkeys(identifiers))
        if not have_sample:
            return YaraRun("compiled", "rule compiles; sample file not found, so it was not tested", found, str(executable))
        if matched:
            return YaraRun("verified", "rule compiles and matches the sample", found, str(executable))
        return YaraRun("no_match", "rule compiles but does NOT match the sample", found, str(executable))
    finally:
        shutil.rmtree(workdir, ignore_errors=True)

