# -- whole-binary result replay ----------------------------------------------------

def _binary_state_key(self, kind: str, options: Mapping[str, Any]) -> Tuple[Any, ...]:
    """Everything a whole-binary result depends on; any difference means "run again"."""
    config = self._config
    manager = self._change_manager
    key: List[Any] = [
        self._change_tracker.generation,                      # any edit in the IDB (IDA events)
        len(manager.audit) if manager is not None else 0,     # approved / rolled-back proposals
        config.provider, config.active_model, config.max_output_tokens,
    ]
    if kind == "analyze_binary":
        key.extend((config.entropy_sample_bytes, config.yara_ai_naming, config.yara_path, config.yara_generalization,
                    config.yara_rules_path))
    elif kind == "sweep":
        key.extend((config.sweep_max_functions, config.sweep_batch_tokens, config.sweep_token_budget, config.sweep_early_stop))
    elif kind == "report":
        notes = options.get("notes")
        key.append(notes.strip() if isinstance(notes, str) else "")
        key.extend((config.yara_ai_naming, config.yara_path, config.yara_generalization, config.yara_rules_path,
                    config.report_max_functions, config.report_token_budget, config.report_ai_verdict))
    return tuple(key)

def _replay_binary_result(self, kind: str, key: Tuple[Any, ...], on_success: Callable[[Any], None],
                          force: bool) -> Optional[str]:
    """Show the previous result instantly (0 tokens) when nothing it depends on changed."""
    cached = self._binary_results.get(kind)
    if force or cached is None or cached[0] != key:
        return None
    _key, result, finished = cached
    log_event(self._logger, "action", kind=kind, success=True, replayed=True, duration=0.0, tokens=0)
    on_success(result)
    return "{0}: previous result from {1} shown instantly (database unchanged, 0 tokens). Shift+click to run it again.".format(
        ACTION_CAPTIONS.get(kind, kind), time.strftime("%H:%M", time.localtime(finished)))

def run_action(
    self,
    kind: str,
    on_success: Callable[[Any], None],
    on_error: Callable[[str], None],
    **options: Any
) -> str:
    """Start one analyst action; returns a short status line immediately.

    Only one action runs at a time. Results of unchanged functions are
    served from ``ResultCache`` without a network call. ``options`` carries
    ``question`` (ask), ``notes`` (report) and ``force`` (bypass cache).
    """
    if kind not in ACTION_KINDS:
        return "Unknown action: {0}".format(kind)
    if self._running_kind is not None:
        if kind == "ask":  # the chat sends a question only when nothing runs (the box keeps it)
            return "Busy: {0} running".format(self._running_kind)
        return self._enqueue(kind, on_success, on_error, options)
    started = time.monotonic()
    self._pending_binary_key = None
    if kind in BINARY_CACHED_KINDS:
        key = self._binary_state_key(kind, options)
        replayed = self._replay_binary_result(kind, key, on_success, bool(options.get("force")))
        if replayed is not None:
            return replayed
        self._pending_binary_key = (kind, key)
    try:
        if kind == "analyze_binary":
            return self._start_analyze_binary(on_success, on_error, started)
        if kind == "suggest_binary_names":
            return self._start_suggest_binary_names(on_success, on_error, started)
        if kind == "sweep":
            return self._start_sweep(on_success, on_error, started)
        if kind == "report":
            return self._start_report(on_success, on_error, options, started)
        return self._start_function_action(kind, on_success, on_error, options, started)
    except (RuntimeError, ValueError) as exc:
        # Prompt loading / provider settings / IDA request failures before the worker started.
        log_event(self._logger, "action", kind=kind, success=False, duration=0.0, error=_log_value(str(exc)))
        return str(exc)
    except Exception as exc:  # never let an unexpected failure escape into IDA's action handler
        self._running_kind = None
        self._task = None
        log_event(self._logger, "action", kind=kind, success=False, duration=0.0, error=_log_value(repr(exc)))
        return "Action failed: {0}".format(type(exc).__name__)

def cancel_action(self, start_next: bool = True) -> None:
    """Stop the running action; the next queued one (if any) then starts."""
    task, self._task = self._task, None
    kind, self._running_kind = self._running_kind, None
    self._pending_binary_key = None
    if task is not None:
        task.cancel()
        log_event(self._logger, "action_cancelled", kind=kind)
    settings_task, self._settings_task = self._settings_task, None
    self._settings_request = None
    if settings_task is not None:
        settings_task.cancel()
    if start_next:
        self._start_next_queued()

def unpack_upx_copy(self) -> str:
    """Triage tab button: ``upx -d`` on a copy, written next to the IDB (only on this click)."""

def _build_yara(self, inputs: Optional["yara_module.YaraInputs"], note: str, sample_path: Optional[str],
                report_path: Path, provider: Optional[LLMProvider], budget: TokenBudget) -> Any:
    """Worker thread: build, optionally AI-name, verify with yara64.exe and save the rule. Never raises."""
    try:
        return self._build_yara_unsafe(inputs, note, sample_path, report_path, provider, budget)
    except Exception as exc:
        log_event(self._logger, "yara_failed", error=_log_value(repr(exc)))
        return yara_module.YaraRuleResult(
            status=yara_module.STATUS_SKIPPED,
            verification="YARA rule could not be built: {0}".format(_log_value(str(exc) or type(exc).__name__)),
        )

def _build_yara_unsafe(self, inputs, note, sample_path, report_path, provider, budget):
    import hashlib

    from ida_ai_malware_analyst_plugin.core.yara_tool import find_yara, verify_rule

    if inputs is None:
        return yara_module.YaraRuleResult(status=yara_module.STATUS_SKIPPED, verification=note or "YARA rule unavailable")
    if yara_module.skip_reason(inputs.classification) is not None:
        return yara_module.build_rule(inputs, None)
    data: Optional[bytes] = None
    sample = Path(sample_path) if sample_path else None
    try:
        if sample is not None and sample.is_file() and sample.stat().st_size <= YARA_MAX_SAMPLE_BYTES:
            data = sample.read_bytes()
    except OSError:
        data = None
    if data is not None:
        inputs = dataclasses.replace(inputs, sha256=hashlib.sha256(data).hexdigest(), file_size=len(data), header=data[:64])
        inputs = self._packed_yara_inputs(inputs, data)
    result = yara_module.build_rule(inputs, data)
    extra_notes: List[str] = [note] if note else []
    if not result.has_rule:
        return dataclasses.replace(result, notes=result.notes + tuple(extra_notes))
    config = self._config
    if config.yara_ai_naming:
        if provider is None:
            extra_notes.append("AI naming is on, but no AI provider is signed in: local name kept.")
        elif budget.exhausted:
            extra_notes.append("AI naming skipped: the report's token budget is used up.")
        else:
            try:
                prompt = self._prompt(PROMPT_FILES["yara_naming"])
                result = yara_module.name_with_ai(result, inputs, provider, prompt, temperature=config.temperature)
            except Exception as exc:
                extra_notes.append("AI naming failed, local name kept: " + _log_value(str(exc) or type(exc).__name__))
    executable = find_yara(config.yara_path, self._plugin_root)
    run = verify_rule(executable, result.text, result.rule_name, str(sample) if data is not None else None)
    detail = run.detail
    if run.status == "verified":
        total = len(result.strings) + len(result.patterns)
        detail += " ({0} of {1} strings / patterns hit)".format(len(run.matched_identifiers), total)
    # Never written automatically: the YARA tab's "Save as…" writes it when the analyst asks.
    del report_path
    log_event(self._logger, "yara_rule", status=run.status, strings=len(result.strings), patterns=len(result.patterns),
              ai_named=result.named_by_ai)
    return dataclasses.replace(
        result, status=run.status, verification=detail, yara_path=run.executable, path="",
        notes=result.notes + tuple(extra_notes),
    )

