    source: str = ""     # rule file name, e.g. "malpedia_win.yar" / "user_rules.yar"
    user: bool = False   # True: from the analyst's own user_rules.yar


def is_user_rule_file(path: Path) -> bool:
    return Path(path).name.lower() == USER_RULES_NAME


def user_hits(result: Optional["RulePackScan"]) -> Tuple[RuleHit, ...]:
    """Matches from the analyst's own ``user_rules.yar`` (empty when none / no scan)."""
    return tuple(hit for hit in (getattr(result, "hits", ()) or ()) if getattr(hit, "user", False))


def hit_kind(hit: RuleHit) -> str:
    """How a hit is described: "your rule" / "curated" / "auto-generated code"."""
    if getattr(hit, "user", False):
        return "your rule"
    return "auto-generated code" if hit.auto else "curated"


