def _merge(hits: Sequence[RuleHit]) -> Tuple[RuleHit, ...]:
    """One hit per family (best ``_rank`` wins; matched offsets of the family are combined)."""
    best: Dict[str, RuleHit] = {}
    for hit in hits:
        kept = best.get(hit.family)
        if kept is None:
            best[hit.family] = hit
            continue
        winner, other = (hit, kept) if _rank(hit) < _rank(kept) else (kept, hit)
        best[hit.family] = RuleHit(**{**winner.__dict__,
                                      "offsets": tuple(dict.fromkeys(winner.offsets + other.offsets))[:MAX_OFFSETS_PER_RULE]})
    return tuple(sorted(best.values(), key=lambda item: (_rank(item), item.family)))


