def generate_yara_anyway(self, on_result: Callable[[Any], None]) -> str:
    """YARA tab "Generate anyway": build the rule that was skipped because user_rules.yar matched.

    Runs on its own worker (local, 0 tokens unless AI naming is on); ``on_result(YaraRuleResult)``
    is called on the UI thread. The replayed Binary Triage / Report results get the new rule too.
    """
    deferred = self._deferred_yara
    if deferred is None:
        return "Nothing to generate: run Binary Triage or Report first"
    if self._yara_task is not None:
        return "The YARA rule is already being generated…"
    inputs, note, sample_path, report_path, provider, budget = deferred

    def done(result: Any) -> None:
        self._yara_task = None
        for kind, cached in list(self._binary_results.items()):
            outcome = cached[1]
            if getattr(getattr(outcome, "yara", None), "status", "") == yara_module.STATUS_COVERED:
                try:
                    self._binary_results[kind] = (cached[0], dataclasses.replace(outcome, yara=result), cached[2])
                except (TypeError, ValueError):
                    pass
        on_result(result)

    def failed(message: str) -> None:
        self._yara_task = None
        on_result(yara_module.YaraRuleResult(status=yara_module.STATUS_SKIPPED,
                                             verification="YARA rule could not be built: " + message))

    task = BackgroundTask(
        work=lambda: self._build_yara(inputs, note, sample_path, report_path, provider, budget, force=True),
