    limits = {"decoder": MAX_DECODER_PATTERNS, "core": MAX_CORE_PATTERNS}
    generic = missing = 0
    ordered = [item for item in sources if item.role == "decoder"] + [item for item in sources if item.role != "decoder"]
    for source in ordered:
        role = "decoder" if source.role == "decoder" else "core"
        if counts[role] >= limits[role] or not source.instructions:
            continue
        if role == "decoder":
            window, why = decoder_window(source)
        else:
            skip = PROLOGUE_INSTRUCTIONS if len(source.instructions) > PROLOGUE_INSTRUCTIONS + 6 else 0
            window, why = best_window(source.instructions, skip), source.why or "core malicious function"
        if window is None:
            continue
        pattern = make_pattern("$c{0}".format(len(chosen) + 1), source, window, why)
        if pattern is None or pattern.hex in seen_hex:
            continue
        hits = count_hits(pattern, data)
        if hits is not None and hits == 0:
            missing += 1
            continue  # IDB bytes differ from the file (patched / unpacked / rebased)
        if hits is not None and hits > MAX_PATTERN_HITS:
            generic += 1
            continue
        seen_hex.add(pattern.hex)
        chosen.append(replace(pattern, hits=hits))
        counts[role] += 1
    if generic:
        notes.append("{0} code pattern(s) dropped: they occur more than {1} times in the sample (too generic).".format(generic, MAX_PATTERN_HITS))
    if missing:
        notes.append("{0} code pattern(s) dropped: the bytes in the IDB are not in the file on disk (patched, unpacked or rebased).".format(missing))
    if data is None and chosen:
        notes.append("Sample file not found on disk: code patterns were not checked for uniqueness.")
    return tuple(chosen), notes


# ---------------------------------------------------------------------------
# Rule text
# ---------------------------------------------------------------------------


def _sanitize(text: str) -> str:
    return re.sub(r"_+", "_", re.sub(r"[^A-Za-z0-9]+", "_", text or "")).strip("_")


def local_rule_name(inputs: YaraInputs) -> str:
    platform = "Win" if inputs.header[:2] == b"MZ" or "pe" in (inputs.file_type or "").lower() else (
        "Linux" if inputs.header[:4] == b"\x7fELF" else "Bin")
    bits = str(inputs.bitness) if inputs.bitness in (32, 64) else ""
    subtype = _sanitize(inputs.subtype.replace("+", " ")) or "Generic"
    family = ""
    if inputs.family_hints:
        family = _sanitize(re.split(r"[(:;,]", inputs.family_hints[0], maxsplit=1)[0])[:24]
    suffix = (inputs.sha256 or "")[:8].upper() or _sanitize(inputs.binary_name)[:12]
    parts = ["MAL", platform + bits, subtype[:40]]
    if family and family.lower() not in subtype.lower():
        parts.append(family)
    parts.append(suffix)
    name = "_".join(part for part in parts if part)
    if not name or not name[0].isalpha():
        name = "MAL_" + name
    return name[:100]


def _local_description(inputs: YaraInputs, patterns: Sequence[RulePattern], string_count: int = 0) -> str:
    what = inputs.subtype or "malware"
    lang = "" if inputs.language in ("", "unknown") else " {0}".format(
        {"go": "Go", "rust": "Rust", "delphi": "Delphi", "dotnet": ".NET", "nim": "Nim"}.get(inputs.language.lower(), inputs.language))
    funcs = ", ".join(dict.fromkeys(item.function for item in patterns if item.function))[:120]
    text = "Detects{0} {1} sample {2}".format(lang, what, inputs.binary_name)
    parts = (["author strings"] if string_count else []) + (["patterns from " + funcs] if funcs else [])
    if parts:
        text += " via " + " and ".join(parts)
    return text[:240]


def _filesize_clause(size: int) -> str:
    if size <= 0:
        return "filesize < 20MB"
    limit = size * 2
    if limit < 1024 * 1024:
        return "filesize < {0}KB".format(int(math.ceil(limit / 1024.0)))
    return "filesize < {0}MB".format(int(math.ceil(limit / (1024.0 * 1024.0))))


def _header_clause(inputs: YaraInputs) -> str:
    if inputs.header[:2] == b"MZ" or (not inputs.header and "pe" in (inputs.file_type or "").lower()):
        return "uint16(0) == 0x5A4D"
    if inputs.header[:4] == b"\x7fELF" or (not inputs.header and "elf" in (inputs.file_type or "").lower()):
        return "uint32(0) == 0x464C457F"
    return ""


def condition_text(string_count: int, pattern_count: int, inputs: YaraInputs) -> str:
    if string_count == 0 and pattern_count == 0:
        return ""
    clauses = [item for item in (_header_clause(inputs), _filesize_clause(inputs.file_size)) if item]
    need = min(string_count, max(2, (string_count * 2 + 2) // 3)) if string_count else 0
    if string_count and pattern_count:
        body = "( {0} of ($s*) and 1 of ($c*) )".format(need)
        if pattern_count >= 2:
            body = "(\n            {0}\n            or 2 of ($c*)\n        )".format(body)
    elif string_count:
        body = "{0} of ($s*)".format(need)
    else:
        body = "2 of ($c*)" if pattern_count >= 2 else "$c1"
    return " and\n        ".join(clauses + [body])


def _meta_value(text: Any) -> str:
    return yara_text_literal(str(text)[:300])


def render_rule(inputs: YaraInputs, name: str, description: str, tags: Sequence[str],
                strings: Sequence[RuleString], patterns: Sequence[RulePattern], generated_at: float) -> str:
    condition = condition_text(len(strings), len(patterns), inputs)
    if not condition:
        return ""
    meta = [
        ("description", description),
        ("author", "IDA AI Malware Analyst (auto-generated draft)"),
        ("date", time.strftime("%Y-%m-%d", time.localtime(generated_at))),
    ]
    if inputs.sha256:
        meta.append(("hash", inputs.sha256.lower()))
    meta.append(("classification", inputs.classification or "MALWARE"))
    if inputs.subtype:
        meta.append(("malware_type", inputs.subtype))
    meta.append(("confidence", "{0}%".format(inputs.confidence)))
    if inputs.family_hints:
        meta.append(("family_hint", inputs.family_hints[0]))
    if any(item.function != "API-hash table" for item in patterns):
        meta.append(("generalization", inputs.generalisation))
    meta.append(("note","Draft from static analysis - tune and test against clean files before deployment"))

    tag_text = (" : " + " ".join(tags)) if tags else ""
    lines = ["rule {0}{1}".format(name, tag_text), "{", "    meta:"]
    width = max(len(key) for key, _value in meta)
    for key, value in meta:
        lines.append("        {0} = {1}".format(key.ljust(width), _meta_value(value)))
    lines += ["", "    strings:"]
    if strings:
        lines.append("        // Distinctive strings referenced by the sample's own code")
        for item in strings:
            comment = " // {0}{1}".format(item.why, " - " + item.function if item.function else "")
            lines.append("        {0} = {1} {2}{3}".format(item.identifier, yara_text_literal(item.value), item.modifiers, comment[:140]))
    for item in patterns:
        lines.append("")
        hits = "" if item.hits is None else ", {0}x in sample".format(item.hits)
        lines.append("        // {0}: {1} @ 0x{2:X} ({3}/{4} bytes fixed{5})".format(
            item.why, item.function or "sub", item.address, item.concrete, item.total, hits))
        lines.append("        {0} = {{".format(item.identifier))
        hex_width = max(len(part) for part, _text in item.lines)
        for part, text in item.lines:
            lines.append("            {0}{1}".format(part.ljust(hex_width), "  // " + text if text else ""))
        lines.append("        }")
    lines += ["", "    condition:", "        " + condition, "}", ""]
    return "\n".join(lines)


def build_rule(inputs: YaraInputs, file_data: Optional[bytes], generated_at: Optional[float] = None) -> YaraRuleResult:
    """Local rule (no AI). ``file_data`` is the sample on disk (``None`` when unavailable)."""
    stamp = time.time() if generated_at is None else generated_at
    reason = skip_reason(inputs.classification)
    if reason is not None:
