# Go buildinfo dependency lines: "dep\tgopkg.in/yaml.v2\tv2.4.0\th1:..." (and "=>" replacements).
_GO_DEP_LINE_RE = re.compile(r"(?:^|\n)\s*(?:dep|=>)\t(?P<module>[^\t\n\r ]+)")
_GO_ESCAPE_RE = re.compile(r"%([0-9A-Fa-f]{2})")


def go_dependency_modules(strings: Iterable[str]) -> FrozenSet[str]:
    """Modules the Go build info lists as dependencies (third-party by definition)."""
    modules: Set[str] = set()
    for value in strings:
        if isinstance(value, str) and "dep\t" in value:
            for match in _GO_DEP_LINE_RE.finditer(value):
                modules.add(match.group("module").strip().lower())
    return frozenset(modules)


def _same_owner(module: str, main_modules: Sequence[str]) -> bool:
    """github.com/<owner>/x and github.com/<owner>/y belong to the same author."""
    parts = module.lower().split("/")
    if len(parts) < 3 or parts[0] not in ("github.com", "gitlab.com", "bitbucket.org", "codeberg.org"):
        return False
    return any(main.lower().split("/")[:2] == parts[:2] for main in main_modules if main.count("/") >= 2)


def _in_modules(package: str, modules: Iterable[str]) -> bool:
    lowered = (package or "").lower()
    return any(lowered == module or lowered.startswith(module + "/") or lowered.startswith(module + ".") for module in modules)


