def _start_next_queued(self) -> None:
    """Start queued actions until one is running (refused or instantly replayed ones are reported)."""
    while self._queue and self._running_kind is None:
        item = self._queue.pop(0)
        delivered = {"done": False}

        def success(result: Any, item: QueuedAction = item, flag: Dict[str, bool] = delivered) -> None:
            flag["done"] = True
            item.on_success(result)

        def error(message: str, item: QueuedAction = item, flag: Dict[str, bool] = delivered) -> None:
            flag["done"] = True
            item.on_error(message)

        try:
            message = self.run_action(item.kind, success, error, **item.options)
        except Exception as exc:  # never let a queued start escape into IDA
            message = "Queued {0} failed to start: {1}".format(item.caption, type(exc).__name__)
        if self._running_kind is None and not delivered["done"]:
            item.on_error("{0}: {1}".format(item.caption, message))  # refused at start (no provider, no function, …)
        if self._running_kind is not None:
            self._panel_queue_changed("Started from queue: {0} - {1}".format(item.caption, message), item.caption)
    self._panel_queue_changed()

