# Open-source Go libraries that malware copies into its own module under a new name (so the
# import path no longer says what it is): library -> the function names that make up its code.
# A package matches when it has >= _COPY_MIN_HITS of these names and they are >= _COPY_MIN_SHARE of
# its own distinct function names (closures, wrappers and init excluded).
_GO_COPIED_LIBRARY_FINGERPRINTS: Dict[str, FrozenSet[str]] = {
    "github.com/kbinani/screenshot": frozenset({
        "capture", "capturerect", "capturedisplay", "numactivedisplays", "getdisplaybounds", "createimage",
        "getdesktopwindow", "enumdisplaymonitors", "getmonitorboundscallback", "getmonitorrealsize",
        "countupmonitorcallback", "getmonitorcallback", "getmonitorinfo", "createcompatiblebitmap",
    }),
}
_COPY_MIN_HITS = 4
_COPY_MIN_SHARE = 0.7
_GO_CLOSURE_SUFFIX_RE = re.compile(r"(?:\.(?:func|deferwrap|gowrap)\d+)+$")


def _go_base_name(name: str, package: str) -> str:
    """``salat_screenshot.Capture.func1`` -> ``capture``; ``pkg._ptr_T.Method`` -> ``method``."""
    text = _GO_CLOSURE_SUFFIX_RE.sub("", name or "")
    tail = text.rsplit(".", 1)[-1] if "." in text else text
    return tail.lower()


def _go_copied_libraries(entries: Sequence[InventoryEntry], origins: Mapping[int, FunctionOrigin]) -> Dict[str, str]:
    """Author packages (never ``main``) that are renamed copies of a known library -> library path."""
    names: Dict[str, Set[str]] = {}
    for item in entries:
        origin = origins.get(item.address)
        if origin is None or origin.origin != AUTHOR or not origin.package or origin.package == "main":
            continue
        base = _go_base_name(item.name, origin.package)
        if base and base != "init" and not base.startswith("init."):
            names.setdefault(origin.package, set()).add(base)
    found: Dict[str, str] = {}
    for package, bases in names.items():
        for library, fingerprint in _GO_COPIED_LIBRARY_FINGERPRINTS.items():
            hits = len(bases & fingerprint)
            if hits >= _COPY_MIN_HITS and hits >= _COPY_MIN_SHARE * len(bases):
                found[package] = library
                break
    return found


