def dominant_category(categories: Sequence[str]) -> Optional[str]:
    """The highest-weighted triage category of a function, or ``None``."""
    if not categories:
        return None
    return max(categories, key=lambda name: (CATEGORY_WEIGHTS.get(name, 0), -categories.index(name)))


def estimate_item_tokens(level: str, instruction_count: int, reference_count: int = 8) -> int:
    if level == "full":
        return FULL_BASE_TOKENS + FULL_PER_INSTRUCTION_TOKENS * max(0, min(instruction_count, MAX_ASSEMBLY_LINES))
    return COMPACT_BASE_TOKENS + COMPACT_PER_REFERENCE_TOKENS * max(0, min(reference_count, 2 * MAX_REFERENCES_PER_FUNCTION))

def _batch_items(
    items: Sequence[SweepItem], adjacency: Mapping[int, Sequence[int]], batch_token_budget: int, system_tokens: int
) -> List[SweepBatch]:
    by_address = {item.address: item for item in items}
    overhead = REQUEST_OVERHEAD_TOKENS + max(0, system_tokens)
    batched: Set[int] = set()
    groups: List[List[SweepItem]] = []
    for item in items:
        if item.address in batched:
            continue
        group = [item]
        tokens = overhead + item.estimated_tokens
        batched.add(item.address)
        if item.instruction_count <= SMALL_FUNCTION_INSTRUCTIONS:
            for child in adjacency.get(item.address, ()):
                candidate = by_address.get(child)
                if candidate is None or child in batched or child == item.address:
                    continue
                if candidate.instruction_count > SMALL_FUNCTION_INSTRUCTIONS or candidate.category != item.category:
                    continue
                if len(group) >= MAX_BATCH_FUNCTIONS or tokens + candidate.estimated_tokens > batch_token_budget:
                    continue
                group.append(candidate)
                tokens += candidate.estimated_tokens
                batched.add(child)
        groups.append(group)

    # Pack runs of lone compact functions together: they carry no code and are independent.
    packed: List[List[SweepItem]] = []
    for group in groups:
        if (
            packed
            and len(group) == 1
            and group[0].level == "compact"
            and all(member.level == "compact" for member in packed[-1])
            and len(packed[-1]) < MAX_BATCH_FUNCTIONS
            and overhead + sum(member.estimated_tokens for member in packed[-1]) + group[0].estimated_tokens <= batch_token_budget
        ):
            packed[-1].append(group[0])
        else:
            packed.append(list(group))

    return [
        SweepBatch(order=index + 1, items=tuple(group), estimated_tokens=overhead + sum(member.estimated_tokens for member in group))
        for index, group in enumerate(packed)
    ]


