def load_sweep_prompt(prompt_path: Any) -> str:
    return load_prompt(prompt_path, "Sweep prompt")


def _text(value: Any, limit: int = MAX_TEXT_CHARS) -> str:
    if not isinstance(value, str):
        return ""
    return " ".join(value.split())[:limit]


def _label(address: int, name: str) -> str:
    return "{0} [0x{1:X}]".format(name, address)


def function_to_request_entry(item: SweepItem, context: FunctionAnalysisContext) -> dict:
    """The per-function JSON sent to the model; ``compact`` carries no code at all."""
    entry: Dict[str, Any] = {
        "address": "0x{0:X}".format(context.function.address),
        "name": context.function.name,
        "representation": item.level,
        "size": context.function.size,
        "triage_score": item.score,
        "signature": context.function.signature,
        "callers": [_label(ref.address, ref.name) for ref in context.callers[:MAX_REFERENCES_PER_FUNCTION]],
        "callees": [_label(ref.address, ref.name) for ref in context.callees[:MAX_REFERENCES_PER_FUNCTION]],
        "referenced_imports_or_globals": [ref.name for ref in context.referenced_names[:MAX_REFERENCES_PER_FUNCTION]],
        "strings": [text[:200] for text in context.strings[:MAX_STRINGS_PER_FUNCTION]],
        "truncated_sections": list(context.truncated_sections),
    }
    if item.level == "full":
        entry["assembly"] = ["0x{0:X} {1}".format(ins.address, ins.text) for ins in context.assembly[:MAX_ASSEMBLY_LINES]]
        entry["pseudocode"] = context.pseudocode[:MAX_PSEUDOCODE_CHARS] if context.pseudocode else None
    return entry


def build_sweep_request(
    batch: SweepBatch,
    contexts: Mapping[int, FunctionAnalysisContext],
    system_prompt: str,
    max_output_tokens: int = 2048,
    temperature: float = 0.2,
) -> LLMRequest:
    entries = [function_to_request_entry(item, contexts[item.address]) for item in batch.items if item.address in contexts]
    payload = {
        "request": SWEEP_REQUEST,
        "batch": batch.order,
        "functions": entries,
        "categories": list(CATEGORIES),
        "indicator_kinds": list(INDICATOR_KINDS),
    }
    return LLMRequest(
        prompt="Analyse these functions and return the required JSON object.\n\n" + json.dumps(payload, ensure_ascii=False),
        system_instruction=system_prompt,
        max_output_tokens=max_output_tokens,
        temperature=temperature,
        response_mime_type="application/json",
    )


