    callers, callers_truncated = (
        _callers(details.address, loaded, limits.max_references) if "callers" in sections else ((), False)
    )
    callees, callees_truncated = (
        _callees(instructions, loaded, limits.max_references) if "callees" in sections else ((), False)
    )
    strings, strings_truncated = (
        _strings_for_instructions(instructions, loaded, limits.max_strings) if "strings" in sections else ((), False)
    )
    blocks, blocks_truncated = (
        _basic_blocks(function, loaded, limits.max_basic_blocks) if "basic_blocks" in sections else ((), False)
    )
    pseudocode, pseudocode_truncated = (
