                  snap: int = CHUNK_SNAP_LINES) -> List[Tuple[int, int]]:
    """``[(first index, end index), ...]`` over ``context.assembly``: overlapping windows cut at block starts."""
    total = len(context.assembly)
    if total <= lines:
        return [(0, total)] if total else []
    block_starts = {block.start_address for block in context.basic_blocks}
    starts_at = [index for index, ins in enumerate(context.assembly) if ins.address in block_starts]
    windows: List[Tuple[int, int]] = []
    first = 0
    while first < total:
        end = min(total, first + lines)
