def _window_weight(context: FunctionAnalysisContext, window: Tuple[int, int]) -> int:
    weight = 0
    names = {ref.name for ref in list(context.callees) + list(context.referenced_names) if ref.name}
    for ins in context.assembly[window[0]:window[1]]:
        text = ins.text or ""
        lowered = text.lower()
        if lowered.startswith("call"):
            weight += 3
        if '"' in text or "offset a" in lowered:
            weight += 2  # string reference
        if any(name in text for name in names):
            weight += 2
    return weight


def select_windows(context: FunctionAnalysisContext, windows: Sequence[Tuple[int, int]], max_chunks: int) -> Tuple[List[Tuple[int, int]], int]:
    """At most ``max_chunks`` windows: the first, then the busiest (calls / references / strings), in order."""
    if len(windows) <= max_chunks:
        return list(windows), 0
    rest = sorted(range(1, len(windows)), key=lambda index: (-_window_weight(context, windows[index]), index))
    chosen = sorted([0] + rest[: max(0, max_chunks - 1)])
    return [windows[index] for index in chosen], len(windows) - len(chosen)


def window_context(context: FunctionAnalysisContext, window: Tuple[int, int]) -> FunctionAnalysisContext:
    """The function's context narrowed to one window: its instructions and the references they name."""
    instructions = tuple(context.assembly[window[0]:window[1]])
    text = "\n".join(ins.text or "" for ins in instructions)
    addresses = {ins.address for ins in instructions}

    def named(refs: Sequence[Any]) -> Tuple[Any, ...]:
        return tuple(ref for ref in refs if (ref.name and ref.name in text) or ref.address in addresses)

    low = instructions[0].address if instructions else context.function.address
    high = instructions[-1].address if instructions else low
    return FunctionAnalysisContext(
        function=context.function,
        assembly=instructions,
        pseudocode=None,
        callers=context.callers,
        callees=named(context.callees),
        strings=tuple(value for value in context.strings if value and value[:24] in text) or tuple(context.strings[:MAX_STRINGS_PER_FUNCTION]),
        basic_blocks=tuple(block for block in context.basic_blocks if low <= block.start_address <= high),
        truncated_sections=("window",),
        referenced_names=named(context.referenced_names),
    )


def build_chunk_request(item: SweepItem, context: FunctionAnalysisContext, index: int, total: int,
                        system_prompt: str, max_output_tokens: int, temperature: float) -> LLMRequest:
    entry = function_to_request_entry(item, context)
    entry["pseudocode"] = None
    first = context.assembly[0].address if context.assembly else context.function.address
    last = context.assembly[-1].address if context.assembly else first
    entry["window"] = {"index": index, "of": total, "first": "0x{0:X}".format(first), "last": "0x{0:X}".format(last)}
    payload = {
        "request": CHUNK_REQUEST.format(index=index, total=total, first="0x{0:X}".format(first), last="0x{0:X}".format(last)),
        "batch": "window {0}/{1}".format(index, total),
        "functions": [entry],
        "categories": list(CATEGORIES),
        "indicator_kinds": list(INDICATOR_KINDS),
    }
    return LLMRequest(
        prompt="Analyse this window of one function and return the required JSON object.\n\n" + json.dumps(payload, ensure_ascii=False),
        system_instruction=system_prompt, max_output_tokens=max_output_tokens, temperature=temperature,
        response_mime_type="application/json",
    )


def _window_findings(results: Sequence[Tuple[Tuple[int, int], "SweepFunctionResult"]], context: FunctionAnalysisContext) -> List[dict]:
    findings = []
    for window, result in results:
        first = context.assembly[window[0]].address
        last = context.assembly[window[1] - 1].address
        findings.append({
            "window": "0x{0:X}-0x{1:X}".format(first, last),
            "summary": result.analysis.summary,
            "observed_behavior": list(result.analysis.observed_behavior),
            "capabilities": [{"category": c.category, "capability": c.capability, "evidence": list(c.evidence),
                              "confidence": c.confidence, "basis": c.basis} for c in result.capabilities],
            "indicators": [{"kind": kind, "value": value} for kind, value in result.indicators],
            "uncertainties": list(result.analysis.uncertainties)[:6],
        })
    return findings


def build_merge_request(item: SweepItem, context: FunctionAnalysisContext, findings: Sequence[dict],
                        system_prompt: str, max_output_tokens: int, temperature: float) -> LLMRequest:
    entry = function_to_request_entry(replace(item, level="compact"), context)  # no code in the merge step
    entry["representation"] = "merged windows (no code)"
    entry["window_findings"] = list(findings)
    payload = {
        "request": MERGE_REQUEST,
        "batch": "merge",
        "functions": [entry],
        "categories": list(CATEGORIES),
        "indicator_kinds": list(INDICATOR_KINDS),
    }
    return LLMRequest(
        prompt="Merge these window findings into one function entry and return the required JSON object.\n\n"
        + json.dumps(payload, ensure_ascii=False),
        system_instruction=system_prompt, max_output_tokens=max_output_tokens, temperature=temperature,
        response_mime_type="application/json",
    )


def merge_window_results(item: SweepItem, context: FunctionAnalysisContext, batch_order: int,
                         results: Sequence[Tuple[Tuple[int, int], "SweepFunctionResult"]],
                         merged: Optional["SweepFunctionResult"], coverage_note: str) -> Optional["SweepFunctionResult"]:
    """One function result from the window results (+ the AI merge, when it succeeded).

    Capabilities, behaviours and indicators are the union of what the windows reported (the merge reply
    may add wording, never facts: its entry is validated against the whole function like any other);
    the summary and suggested name come from the merge reply, or from the windows when it failed.
    The combined entry is re-validated against the full function context.
    """
    if not results:
        return None
    capabilities: Dict[Tuple[str, str], dict] = {}
    observed: List[str] = []
    indicators: List[dict] = []
    uncertainties: List[str] = [coverage_note]
    sources = [result for _window, result in results] + ([merged] if merged is not None else [])
    for result in sources:
        for capability in result.capabilities:
            key = (capability.category, capability.capability.strip().lower())
            current = capabilities.get(key)
            if current is None or capability.confidence > current["confidence"]:
                capabilities[key] = {"category": capability.category, "capability": capability.capability,
                                     "evidence": list(capability.evidence)[:8], "confidence": capability.confidence,
                                     "basis": capability.basis}
        for line in result.analysis.observed_behavior:
            if line not in observed:
                observed.append(line)
        for kind, value in result.indicators:
            if {"kind": kind, "value": value} not in indicators:
                indicators.append({"kind": kind, "value": value})
    for _window, result in results:
        for line in result.analysis.uncertainties:
            if line not in uncertainties and not line.startswith("0x"):
                uncertainties.append(line)
    if merged is not None:
        summary = merged.analysis.summary
        suggested = merged.analysis.suggested_name
    else:
        summary = " ".join(result.analysis.summary for _window, result in results)[:1000]
        suggested = next((result.analysis.suggested_name for _window, result in results if result.analysis.suggested_name), None)
        uncertainties.append("window summaries joined locally (the merge request did not succeed)")
    entry = {
        "address": "0x{0:X}".format(item.address), "summary": summary, "observed_behavior": observed[:MAX_LIST_ITEMS],
        "capabilities": list(capabilities.values())[:MAX_LIST_ITEMS], "suggested_name": suggested,
        "indicators": indicators[:MAX_LIST_ITEMS], "uncertainties": uncertainties[:MAX_LIST_ITEMS],
    }
    batch = SweepBatch(order=batch_order, items=(item,), estimated_tokens=0)
    final, _notes = parse_sweep_response(json.dumps({"functions": [entry]}), batch, {item.address: context})
    return final[0] if final else None


