        narrow = window_context(deep, window)
        request = build_chunk_request(item, narrow, position, len(chosen), system_prompt, max_output_tokens, temperature)
        raw = ask(request, "{0} window {1}/{2}".format(label, position, len(chosen)))
        if raw is None:
            continue
        single = SweepBatch(order=batch_order, items=(item,), estimated_tokens=0)
        try:
            parsed, notes = parse_sweep_response(raw, single, {item.address: narrow})
        except SweepResponseError as exc:
            uncertainties.append("{0} window {1}: {2}".format(label, position, exc))
            continue
        uncertainties.extend(notes)
        if parsed:
            results.append((window, parsed[0]))
        progress("batch {0}: {1} window {2}/{3} analysed".format(batch_order, label, position, len(chosen)))
    if not results:
        return None
    covered = len({index for window, _r in results for index in range(window[0], window[1])})
    note = "large function analysed in {0} window(s): {1} of {2} instructions read{3}{4}".format(
        len(results), covered, len(deep.assembly),
        "; {0} quieter window(s) without calls / strings not sent".format(skipped) if skipped else "",
        "; deep read stopped at {0} instructions".format(LARGE_FUNCTION_MAX_INSTRUCTIONS) if "assembly" in deep.truncated_sections else "")
    merged: Optional[SweepFunctionResult] = None
    if len(results) > 1 and not cancelled() and not budget.exhausted:
        request = build_merge_request(item, deep, _window_findings(results, deep), system_prompt, max_output_tokens, temperature)
        raw = ask(request, "{0} merge".format(label))
        if raw is not None:
            try:
                parsed, notes = parse_sweep_response(raw, SweepBatch(order=batch_order, items=(item,), estimated_tokens=0),
                                                     {item.address: deep})
                uncertainties.extend(notes)
                merged = parsed[0] if parsed else None
            except SweepResponseError as exc:
                uncertainties.append("{0} merge: {1}".format(label, exc))
    elif len(results) == 1:
        merged = results[0][1]
    final = merge_window_results(item, deep, batch_order, results, merged, note)
    return final if final is not None else results[0][1]

