"""Token budgets and estimates shared by the metered provider and the binary sweep.

No IDA, no network. ``estimate_tokens`` is a deliberately simple, provider
neutral approximation (four characters per token); real usage numbers from a
provider response replace the estimate whenever they are present.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, Mapping, Optional


def estimate_tokens(text: Any) -> int:
    """Rough token count for ``text``: ``max(1, len(text) // 4)``; non-strings count as their ``str``."""
    if text is None:
        return 1
    value = text if isinstance(text, str) else str(text)
    return max(1, len(value) // 4)


def format_tokens(count: int) -> str:
    """``~950 tokens`` / ``~18.2k tokens`` / ``~1.3M tokens`` for status lines."""
    value = max(0, int(count))
    if value >= 1_000_000:
        return "~{0:.1f}M tokens".format(value / 1_000_000.0)
    if value >= 1000:
        return "~{0:.1f}k tokens".format(value / 1000.0)
    return "~{0} tokens".format(value)


def usage_counts(usage: Any) -> Optional[Dict[str, int]]:
    """Validate a ``{"input": int, "output": int}`` mapping; ``None`` when unusable."""
    if not isinstance(usage, Mapping):
        return None
    counts: Dict[str, int] = {}
    for key in ("input", "output"):
        value = usage.get(key)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            return None
        counts[key] = value
    return counts


@dataclass(frozen=True)
class UsageRecord:
    """One charged provider call."""

    input_tokens: int
    output_tokens: int
    estimated: bool

    @property
    def total(self) -> int:
        return self.input_tokens + self.output_tokens


class TokenBudget:
    """Cumulative token counter with an optional ceiling.

    ``max_tokens=None`` makes an unbounded counter (the per-session meter);
    a positive integer makes a budget that reports ``exhausted`` once the
    charged total reaches it (the per-sweep budget).
    """

    def __init__(self, max_tokens: Optional[int] = None) -> None:
        if max_tokens is not None and (isinstance(max_tokens, bool) or not isinstance(max_tokens, int) or max_tokens <= 0):
            raise ValueError("max_tokens must be a positive integer or None")
        self.max_tokens = max_tokens
        self._input = 0
        self._output = 0
        self._requests = 0
        self._estimated_requests = 0

    # -- accounting -----------------------------------------------------------

    def charge(self, request_text: Any, response_text: Any, usage: Any = None) -> UsageRecord:
        """Charge one call; real ``usage`` counts win over the text estimate."""
        counts = usage_counts(usage)
        if counts is not None:
            record = UsageRecord(counts["input"], counts["output"], False)
        else:
            record = UsageRecord(estimate_tokens(request_text), estimate_tokens(response_text), True)
        self._input += record.input_tokens
        self._output += record.output_tokens
        self._requests += 1
        if record.estimated:
            self._estimated_requests += 1
        return record

    def reserve_ok(self, request_text: Any) -> bool:
        """Whether an upcoming request of this size still fits (unbounded budgets always fit)."""
        if self.max_tokens is None:
            return True
        return self.used + estimate_tokens(request_text) <= self.max_tokens

    # -- state ---------------------------------------------------------------

    @property
    def used(self) -> int:
        return self._input + self._output

    @property
    def input_tokens(self) -> int:
        return self._input

    @property
    def output_tokens(self) -> int:
        return self._output

    @property
    def requests(self) -> int:
        return self._requests

    @property
    def estimated_requests(self) -> int:
        return self._estimated_requests

    @property
    def remaining(self) -> Optional[int]:
        if self.max_tokens is None:
            return None
        return max(0, self.max_tokens - self.used)

    @property
    def exhausted(self) -> bool:
        return self.max_tokens is not None and self.used >= self.max_tokens

    def snapshot(self) -> Dict[str, Any]:
        return {
            "used": self.used,
            "input": self._input,
            "output": self._output,
            "requests": self._requests,
            "estimated_requests": self._estimated_requests,
            "max_tokens": self.max_tokens,
        }

    def describe(self) -> str:
        return format_tokens(self.used)


__all__ = ["TokenBudget", "UsageRecord", "estimate_tokens", "format_tokens", "usage_counts"]
