        line = "{0} done ({1} request(s) answered, {2} function(s) analysed, {3})".format(
            job.label, counters["answered"], len(findings), format_tokens(budget.used - start_tokens))
        trace.append(line)
        progress(line)

    source = jobs_from_plan()
    queue: "deque" = deque()        # merges first (appendleft), then retries; new plan jobs come from ``source``
    running: Dict[Any, _Job] = {}
    exhausted_source = False
    stop_new = False
    with futures.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="aima-report") as pool:
        while True:
            while len(running) < workers and not stop_new:
                if cancelled():
                    reason, stop_new = "cancelled", True
                    break
                job = queue.popleft() if queue else None
                if job is None and not exhausted_source:
                    job = next(source, None)
                    if job is None:
                        exhausted_source = True
                if job is None:
                    break
                _text_unused, tokens = estimate(job.request)
                if budget.max_tokens is not None and budget.used + in_flight_tokens[0] + tokens > budget.max_tokens:
                    uncertainties.append("{0} skipped: the token budget would be exceeded".format(job.label))
                    reason = "budget"
                    if job.group is not None and not job.group.done:
                        job.group.pending = 0
                        finish_group(job.group, None)
                    stop_new = True
                    break
                job.estimate = tokens
                in_flight_tokens[0] += tokens
                running[pool.submit(call, job)] = job
            if not running:
                if (queue or not exhausted_source) and not stop_new:
                    continue  # merges / retries queued while nothing ran
                break
            done, _pending = futures.wait(list(running), return_when=futures.FIRST_COMPLETED)
            for future in done:
                job = running.pop(future)
                in_flight_tokens[0] -= job.estimate
                try:
                    text, error, usage = future.result()
                except Exception as exc:  # defensive: ``call`` already catches provider errors
                    text, error, usage = None, type(exc).__name__, None
                handle(job, text, error, usage, queue)
            if budget.exhausted and not stop_new:
                reason, stop_new = "budget", True
        # Windowed functions whose windows came back but whose merge never ran (budget / cancel).
    for job in list(queue):
        if job.group is not None and not job.group.done:
            finish_group(job.group, None)
    if cancelled() and reason == "complete":
        reason = "cancelled"

    ordered = sorted(findings.values(), key=lambda result: order.get(result.address, len(order)))
    strong: Dict[str, int] = {}
    concrete: Dict[str, int] = {}
    for result in ordered:
        for capability in result.capabilities:
            if capability.strong:
                strong[capability.category] = strong.get(capability.category, 0) + 1
            if capability.concrete:
                concrete[capability.category] = concrete.get(capability.category, 0) + 1
    score = signal_score(strong, base_score, base_categories)
    summary = SweepSummary(
        functions_planned=plan.functions_planned, functions_analysed=len(ordered), batches=counters["batches"],
        requests=counters["requests"], tokens_used=budget.used - start_tokens, stopped_reason=reason,
        pruned_noise_count=plan.pruned_noise_count,
    )
    state = SweepState(
        planned=plan.functions_planned, analysed=len(ordered), batches_done=counters["batches"], requests=counters["requests"],
        tokens_used=summary.tokens_used, strong_by_category=dict(strong), score=score, band=band_for(score),
        findings=tuple(ordered), concrete_by_category=dict(concrete),
    )
    trace.append(format_sweep_summary(summary) + " ({0} parallel request(s))".format(workers))
    return SweepResult(plan=plan, functions=tuple(ordered), state=state, summary=summary,
                       uncertainties=tuple(dict.fromkeys(uncertainties)), trace=tuple(trace))


