# --------------------------------------------------------------------------- #
# Run: parallel requests (Report)
# --------------------------------------------------------------------------- #

MAX_PARALLEL_REQUESTS = 8
_RETRIES_PER_REQUEST = 1


@dataclass
class _Job:
    kind: str                                   # "batch" | "window" | "merge"
    request: LLMRequest
    label: str
    batch: Optional[SweepBatch] = None
    contexts: Optional[Dict[int, FunctionAnalysisContext]] = None
    group: Optional["_LargeGroup"] = None
    window: Optional[Tuple[int, int]] = None
    attempts: int = 0
    estimate: int = 0


@dataclass
class _LargeGroup:
    item: SweepItem
    deep: FunctionAnalysisContext
    batch_order: int
    chosen: List[Tuple[int, int]]
    skipped: int
    pending: int
    results: List[Tuple[Tuple[int, int], "SweepFunctionResult"]] = field(default_factory=list)
    done: bool = False


def _run_sweep_parallel(
    plan: SweepPlan,
    collect_context: Callable[[int, str], Optional[FunctionAnalysisContext]],
    provider: LLMProvider,
    system_prompt: str,
    budget: TokenBudget,
    cancelled: Callable[[], bool],
    progress: Callable[[str], None],
    max_output_tokens: int,
    temperature: float,
    base_score: int,
    base_categories: FrozenSet[str],
    collect_large: Optional[Callable[[int], Optional[FunctionAnalysisContext]]],
    max_chunks: int,
    parallel: int,
) -> SweepResult:
    """``run_sweep`` with up to ``parallel`` model requests in flight.

    Context reads (IDA) stay on this thread, one at a time, while earlier requests are answered.
    Every request is budget-checked including the tokens of requests still in flight, every reply is
    parsed and validated here (this thread), a large function's merge starts once all its windows
    are back, a failed request is retried once, and findings come back in plan order.
    """
    import concurrent.futures as futures
    from collections import deque

    workers = max(1, min(int(parallel), MAX_PARALLEL_REQUESTS))
    start_tokens = budget.used
    provider_meters_budget = getattr(provider, "budget", None) is budget
    chunking = collect_large is not None and isinstance(max_chunks, int) and max_chunks > 0
    order = {item.address: index for index, item in enumerate(plan.items)}
    findings: Dict[int, SweepFunctionResult] = {}
    uncertainties: List[str] = []
    trace: List[str] = []
    counters = {"requests": 0, "batches": 0, "answered": 0}
    reason = "complete"
    in_flight_tokens = [0]

    def estimate(request: LLMRequest) -> Tuple[str, int]:
        text = (request.system_instruction or "") + request.prompt
        return text, max(1, len(text) // 4)

    def call(job: _Job) -> Tuple[Optional[str], Optional[str], Any]:
        """Pool thread: the model call only. Returns (reply text, error text, usage)."""
        if cancelled():
            return None, "cancelled", None
        try:
            response = provider.generate(job.request)
        except Exception as exc:  # recorded and retried by the main loop
            return None, _text(str(exc), 200) or type(exc).__name__, None
        return response.text, None, getattr(response, "usage", None)

    def jobs_from_plan():
        """Lazily read contexts (this thread) and yield the requests, batch by batch."""
        for batch in plan.batches:
            if cancelled():
                return
            contexts: Dict[int, FunctionAnalysisContext] = {}
            for item in batch.items:
                try:
                    context = collect_context(item.address, item.level)
                except Exception as exc:
                    context = None
                    uncertainties.append("0x{0:X}: context collection failed ({1})".format(item.address, type(exc).__name__))
                if context is None:
                    uncertainties.append("0x{0:X}: no context available; skipped".format(item.address))
                    continue
                contexts[item.address] = context
            if chunking:
                for item in batch.items:
                    if item.address not in contexts or not needs_chunking(item, contexts[item.address]):
                        continue
                    try:
                        deep = collect_large(item.address)  # type: ignore[misc]
                    except Exception as exc:
                        deep = None
                        uncertainties.append("0x{0:X}: deep read failed ({1}); analysed from the first {2} instructions".format(
                            item.address, type(exc).__name__, MAX_ASSEMBLY_LINES))
                    if deep is None or len(deep.assembly) <= MAX_ASSEMBLY_LINES:
                        continue
                    chosen, skipped = select_windows(deep, chunk_windows(deep), max_chunks)
                    group = _LargeGroup(item, deep, batch.order, chosen, skipped, pending=len(chosen))
                    label = "{0} [0x{1:X}]".format(deep.function.name, item.address)
                    del contexts[item.address]
                    for position, window in enumerate(chosen, 1):
                        narrow = window_context(deep, window)
                        request = build_chunk_request(item, narrow, position, len(chosen), system_prompt, max_output_tokens, temperature)
                        yield _Job("window", request, "{0} window {1}/{2}".format(label, position, len(chosen)),
                                   batch=SweepBatch(order=batch.order, items=(item,), estimated_tokens=0),
                                   contexts={item.address: narrow}, group=group, window=window)
            counters["batches"] += 1
            if contexts:
                normal = replace(batch, items=tuple(item for item in batch.items if item.address in contexts))
                request = build_sweep_request(normal, contexts, system_prompt, max_output_tokens, temperature)
                yield _Job("batch", request, "batch {0}".format(batch.order), batch=normal, contexts=contexts)

    def finish_group(group: _LargeGroup, merged: Optional[SweepFunctionResult]) -> None:
        group.done = True
        if not group.results:
            return
        covered = len({index for window, _r in group.results for index in range(window[0], window[1])})
        note = "large function analysed in {0} window(s): {1} of {2} instructions read{3}{4}".format(
            len(group.results), covered, len(group.deep.assembly),
            "; {0} quieter window(s) without calls / strings not sent".format(group.skipped) if group.skipped else "",
            "; deep read stopped at {0} instructions".format(LARGE_FUNCTION_MAX_INSTRUCTIONS)
            if "assembly" in group.deep.truncated_sections else "")
        group.results.sort(key=lambda pair: pair[0][0])
        if merged is None and len(group.results) == 1:
            merged = group.results[0][1]
        final = merge_window_results(group.item, group.deep, group.batch_order, group.results, merged, note)
        findings[group.item.address] = final if final is not None else group.results[0][1]

    def handle(job: _Job, text: Optional[str], error: Optional[str], usage: Any, retry: "deque") -> None:
        request_text, _tokens = estimate(job.request)
        counters["requests"] += 1
        if not provider_meters_budget:
            budget.charge(request_text, text or "", usage)
        if error is not None:
            if error != "cancelled" and job.attempts < _RETRIES_PER_REQUEST:
                job.attempts += 1
                retry.append(job)
                return
            uncertainties.append("{0}: model request failed ({1})".format(job.label, error))
            text = None
        results: List[SweepFunctionResult] = []
        if text is not None:
            try:
                results, notes = parse_sweep_response(text, job.batch, job.contexts or {})  # type: ignore[arg-type]
                uncertainties.extend(notes)
            except SweepResponseError as exc:
                uncertainties.append("{0}: {1}".format(job.label, exc))
        if job.kind == "batch":
            for result in results:
                findings[result.address] = result
        elif job.kind == "window" and job.group is not None:
            group = job.group
            if results:
                group.results.append((job.window, results[0]))  # type: ignore[arg-type]
            group.pending -= 1
            if group.pending == 0 and not group.done:
                if len(group.results) > 1 and not cancelled() and not budget.exhausted:
                    request = build_merge_request(group.item, group.deep, _window_findings(sorted(group.results, key=lambda p: p[0][0]), group.deep),
                                                  system_prompt, max_output_tokens, temperature)
                    retry.appendleft(_Job("merge", request, "{0} [0x{1:X}] merge".format(group.deep.function.name, group.item.address),
                                          batch=SweepBatch(order=group.batch_order, items=(group.item,), estimated_tokens=0),
                                          contexts={group.item.address: group.deep}, group=group))
                else:
                    finish_group(group, None)
        elif job.kind == "merge" and job.group is not None:
            finish_group(job.group, results[0] if results else None)
        counters["answered"] += 1
        line = "{0} done ({1} request(s) answered, {2} function(s) analysed, {3})".format(
            job.label, counters["answered"], len(findings), format_tokens(budget.used - start_tokens))
        trace.append(line)
        progress(line)

    source = jobs_from_plan()
    queue: "deque" = deque()        # merges first (appendleft), then retries; new plan jobs come from ``source``
    running: Dict[Any, _Job] = {}
    exhausted_source = False
    stop_new = False
    with futures.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="aima-report") as pool:
        while True:
            while len(running) < workers and not stop_new:
                if cancelled():
                    reason, stop_new = "cancelled", True
                    break
                job = queue.popleft() if queue else None
                if job is None and not exhausted_source:
                    job = next(source, None)
                    if job is None:
                        exhausted_source = True
                if job is None:
                    break
                _text_unused, tokens = estimate(job.request)
                if budget.max_tokens is not None and budget.used + in_flight_tokens[0] + tokens > budget.max_tokens:
                    uncertainties.append("{0} skipped: the token budget would be exceeded".format(job.label))
                    reason = "budget"
                    if job.group is not None and not job.group.done:
                        job.group.pending = 0
                        finish_group(job.group, None)
                    stop_new = True
                    break
                job.estimate = tokens
                in_flight_tokens[0] += tokens
                running[pool.submit(call, job)] = job
            if not running:
                if (queue or not exhausted_source) and not stop_new:
                    continue  # merges / retries queued while nothing ran
                break
            done, _pending = futures.wait(list(running), return_when=futures.FIRST_COMPLETED)
            for future in done:
                job = running.pop(future)
                in_flight_tokens[0] -= job.estimate
                try:
                    text, error, usage = future.result()
                except Exception as exc:  # defensive: ``call`` already catches provider errors
                    text, error, usage = None, type(exc).__name__, None
                handle(job, text, error, usage, queue)
            if budget.exhausted and not stop_new:
                reason, stop_new = "budget", True
        # Windowed functions whose windows came back but whose merge never ran (budget / cancel).
    for job in list(queue):
        if job.group is not None and not job.group.done:
            finish_group(job.group, None)
    if cancelled() and reason == "complete":
        reason = "cancelled"

    ordered = sorted(findings.values(), key=lambda result: order.get(result.address, len(order)))
    strong: Dict[str, int] = {}
    concrete: Dict[str, int] = {}
    for result in ordered:
        for capability in result.capabilities:
            if capability.strong:
                strong[capability.category] = strong.get(capability.category, 0) + 1
            if capability.concrete:
                concrete[capability.category] = concrete.get(capability.category, 0) + 1
    score = signal_score(strong, base_score, base_categories)
    summary = SweepSummary(
        functions_planned=plan.functions_planned, functions_analysed=len(ordered), batches=counters["batches"],
        requests=counters["requests"], tokens_used=budget.used - start_tokens, stopped_reason=reason,
        pruned_noise_count=plan.pruned_noise_count,
    )
    state = SweepState(
        planned=plan.functions_planned, analysed=len(ordered), batches_done=counters["batches"], requests=counters["requests"],
        tokens_used=summary.tokens_used, strong_by_category=dict(strong), score=score, band=band_for(score),
        findings=tuple(ordered), concrete_by_category=dict(concrete),
    )
    trace.append(format_sweep_summary(summary) + " ({0} parallel request(s))".format(workers))
    return SweepResult(plan=plan, functions=tuple(ordered), state=state, summary=summary,
                       uncertainties=tuple(dict.fromkeys(uncertainties)), trace=tuple(trace))


