"""Database change counter from IDA's own ``IDB_Hooks`` (core IDA; no Hex-Rays).

Every event that can change what the whole-binary actions see - renames,
comments, patches, types, functions and code/data being created or deleted -
bumps ``generation``. The controller replays a previous Binary Triage / Report
/ sweep result only while the generation is unchanged, so any edit, whether
made by the analyst in IDA or by an approved proposal, triggers a fresh run.
"""

from __future__ import annotations

from typing import Callable, Optional

try:
    import ida_idp
except ImportError:  # outside IDA (tests)
    ida_idp = None

# IDB_Hooks callbacks that mean "the database changed" (all return 0 = continue).
EVENTS = (
    "renamed", "cmt_changed", "extra_cmt_changed", "range_cmt_changed", "byte_patched", "ti_changed", "op_type_changed",
    "func_added", "deleting_func", "func_updated", "set_func_start", "set_func_end", "func_tail_appended",
    "func_tail_deleted", "make_code", "make_data", "destroyed_items", "segm_added", "deleting_segm",
    "local_types_changed", "lt_udt_changed", "lt_edm_changed",
)


class ChangeTracker:
    """``generation`` grows on every database change event; ``bump()`` for changes made without hooks."""

    def __init__(self) -> None:
        self.generation = 0
        self._hooks = None

    def bump(self, *args: object) -> int:
        del args
        self.generation += 1
        return 0

    def install(self) -> bool:
        base = getattr(ida_idp, "IDB_Hooks", None) if ida_idp is not None else None
        if base is None or self._hooks is not None:
            return False
        bump: Callable[..., int] = self.bump
        methods = {name: (lambda self_, *args, _bump=bump: _bump()) for name in EVENTS}
        try:
            hooks = type("_AiAnalystChangeHooks", (base,), methods)()
            if hooks.hook():
                self._hooks = hooks
                return True
        except Exception:
            self._hooks = None
        return False

    def uninstall(self) -> None:
        hooks, self._hooks = self._hooks, None
        if hooks is not None:
            try:
                hooks.unhook()
            except Exception:
                pass

    @property
    def active(self) -> bool:
        return self._hooks is not None


__all__ = ["ChangeTracker", "EVENTS"]

