def _pseudocode(address: int, modules: IdaModules, maximum: int) -> Tuple[Optional[str], bool]:
    if modules.hexrays is None:
        return None, False
    try:
        initializer = getattr(modules.hexrays, "init_hexrays_plugin", None)
        if callable(initializer) and not initializer():
            return None, False
        cfunc = modules.hexrays.decompile(address)
        if cfunc is None:
            return None, False
        pseudocode = str(cfunc)
    except Exception:
        # ``ida_hexrays.DecompilationFailure`` derives from ``Exception`` directly,
        # so a narrower clause would let a failed decompilation escape into IDA.
        return None, False
    if len(pseudocode) > maximum:
        return pseudocode[:maximum], True
    return pseudocode, False

def _decompile(address: int, modules: IdaModules) -> Optional[Any]:
    if modules.hexrays is None:
        return None
    start = _function_start(address, modules)
    if start is None:
        return None
    try:
        initializer = getattr(modules.hexrays, "init_hexrays_plugin", None)
        if callable(initializer) and not initializer():
            return None
        return modules.hexrays.decompile(start)
    except Exception:
        # Includes ida_hexrays.DecompilationFailure, which is only defined inside IDA.
        return None

