"""Hex-Rays local-variable reader and writer using injected IDA modules.

All IDAPython access for Phase 7 lives here. Every entry point accepts an
``IdaModules`` instance so the behaviour is testable with plain mocks, and
each returns an empty/false/``None`` value when Hex-Rays is unavailable or
decompilation fails rather than raising inside IDA.
"""

from __future__ import annotations

import re
from typing import Any, Optional, Tuple

from ida_ai_malware_analyst_plugin.analysis.naming import LocalVariable
from ida_ai_malware_analyst_plugin.ida.compatibility import IdaModules, load_ida_modules


_IDENTIFIER_PATTERN = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,127}")


def collect_local_variables(address: int, modules: Optional[IdaModules] = None) -> Tuple[LocalVariable, ...]:
    """Return the named Hex-Rays locals/arguments of the function at ``address``."""
    _check_address(address)
    loaded = modules or load_ida_modules()
    cfunc = _decompile(address, loaded)
    if cfunc is None:
        return ()
    try:
        lvars = cfunc.get_lvars()
    except Exception:
        return ()
    collected = []
    seen = set()
    for lvar in _iterate(lvars):
        name = _value(lvar, "name")
        if not isinstance(name, str) or not name.strip() or name in seen:
            continue
        seen.add(name)
        collected.append(LocalVariable(name=name, type_str=_type_text(lvar), is_arg=bool(_value(lvar, "is_arg_var"))))
    return tuple(collected)


def read_local_variable_name(address: int, name: str, modules: Optional[IdaModules] = None) -> Optional[str]:
    """Return ``name`` when such a local exists in the function, else ``None``.

    This is the ``ChangeManager`` reader for ``rename_variable``: ``None``
    marks the target as not safely writable.
    """
    if not isinstance(name, str) or not name:
        return None
    for variable in collect_local_variables(address, modules):
        if variable.name == name:
            return variable.name
    return None


def rename_local_variable(address: int, old_name: str, new_name: str, modules: Optional[IdaModules] = None) -> bool:
    """Rename one Hex-Rays local via ``ida_hexrays.rename_lvar``; ``False`` on any failure."""
    _check_address(address)
    if not (isinstance(old_name, str) and isinstance(new_name, str)):
        return False
    if not _IDENTIFIER_PATTERN.fullmatch(new_name) or old_name == new_name:
        return False
    loaded = modules or load_ida_modules()
    if loaded.hexrays is None:
        return False
    rename = getattr(loaded.hexrays, "rename_lvar", None)
    if not callable(rename):
        return False
    start = _function_start(address, loaded)
    if start is None or read_local_variable_name(start, old_name, loaded) is None:
        return False
    try:
        return bool(rename(start, old_name, new_name))
    except Exception:
        return False


def _check_address(address: int) -> None:
    if not isinstance(address, int) or isinstance(address, bool) or address < 0:
        raise ValueError("Function address must be a non-negative integer")


def _function_start(address: int, modules: IdaModules) -> Optional[int]:
    if modules.funcs is None:
        return address
    try:
        function = modules.funcs.get_func(address)
    except Exception:
        return None
    if function is None:
        return None
    return getattr(function, "start_ea", address)


def _decompile(address: int, modules: IdaModules) -> Optional[Any]:
    if modules.hexrays is None:
        return None
    start = _function_start(address, modules)
    if start is None:
        return None
    try:
        initializer = getattr(modules.hexrays, "init_hexrays_plugin", None)
        if callable(initializer) and not initializer():
            return None
        return modules.hexrays.decompile(start)
    except Exception:
        # Includes ida_hexrays.DecompilationFailure, which is only defined inside IDA.
        return None


def _iterate(lvars: Any):
    try:
        return list(lvars)
    except TypeError:
        pass
    try:
        return [lvars[index] for index in range(lvars.size())]
    except Exception:
        return []


def _value(target: Any, attribute: str) -> Any:
    """Read an attribute that is a property in some IDA versions and a method in others."""
    value = getattr(target, attribute, None)
    if callable(value):
        try:
            return value()
        except Exception:
            return None
    return value


def _type_text(lvar: Any) -> str:
    tif = _value(lvar, "type")
    if tif is None:
        return ""
    for renderer in ("dstr", "_print"):
        text = _value(tif, renderer)
        if isinstance(text, str) and text.strip():
            return text.strip()
    try:
        return str(tif).strip()
    except Exception:
        return ""

