def _local_answer(self, question: str) -> Optional[str]:
    """Answer "what does X do?"-style questions from the local analysis database (no tokens).

    Only when the question names an analysed function (by name or ``0x`` address) and asks
    about its behaviour. Prefix a question with ``!`` to always ask the model.
    """
    store = self._analysis_store()
    if store is None or question.startswith("!"):
        return None
    if not _LOCAL_QUESTION_RE.search(question):
        return None
    records = [record for record in store.find_functions(question) if record.kind in STORED_ANALYSIS_KINDS + ("capabilities",)]
    if not records:
        return None
    lines = ["(answered from the local analysis database — no tokens used; prefix with ! to ask the model)"]
    for address in dict.fromkeys(record.address for record in records):
        group = [record for record in records if record.address == address]
        name = group[0].name
        lines.append("")
        lines.append("{0} @ 0x{1:X}".format(name, address))
        for record in sorted(group, key=lambda item: -item.updated_at):
            if record.summary:
                lines.append("  [{0}] {1}".format(record.kind.replace("_", " "), record.summary))
            analysis = record.payload.get("analysis") if isinstance(record.payload.get("analysis"), dict) else record.payload
            for key, label in (("observed_behavior", "observed"), ("important_apis", "APIs"), ("evidence", "evidence")):
                values = analysis.get(key) if isinstance(analysis, dict) else None
                if isinstance(values, list) and values:
                    lines.append("  {0}: {1}".format(label, "; ".join(str(item) for item in values[:5])))
            for cap in (record.payload.get("capabilities") or [])[:5]:
                if isinstance(cap, dict):
                    lines.append("  capability: {0} — {1} ({2})".format(cap.get("category"), cap.get("capability"), cap.get("basis")))
    return "\n".join(lines)

"""Typed function-analysis prompt construction and model-output validation."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Optional, Tuple

from ida_ai_malware_analyst_plugin.core.context import FunctionAnalysisContext
from ida_ai_malware_analyst_plugin.core.parsing import strip_json_fence
from ida_ai_malware_analyst_plugin.llm.base import LLMProvider, LLMRequest


class AnalysisResponseError(ValueError):
    """The model response cannot be safely rendered as a function analysis."""


@dataclass(frozen=True)
class FunctionAnalysis:
    summary: str
    observed_behavior: Tuple[str, ...]
    inferences: Tuple[str, ...]
    hypotheses: Tuple[str, ...]
    important_apis: Tuple[str, ...]
    important_strings: Tuple[str, ...]
    related_functions: Tuple[str, ...]
    evidence: Tuple[str, ...]
    behavior_confidence: float
    uncertainties: Tuple[str, ...]
    suggested_name: Optional[str]

    @property
    def confidence_label(self) -> str:
        if self.behavior_confidence >= 0.75:
            return "High"
        if self.behavior_confidence >= 0.45:
            return "Medium"
        return "Low"


def load_prompt(prompt_path: Path, label: str = "Prompt") -> str:
    """Read one shipped prompt file; the single loader used by every analysis module.

    ``label`` names the prompt in error messages (e.g. ``"Naming prompt"``).
    Raises ``RuntimeError`` when the file is unreadable or empty so callers can
    show one safe status line instead of an OS error.
    """
    try:
        prompt = Path(prompt_path).read_text(encoding="utf-8").strip()
    except OSError as exc:
        raise RuntimeError("{0} could not be loaded".format(label)) from exc
    if not prompt:
        raise RuntimeError("{0} is empty".format(label))
    return prompt


def load_function_prompt(prompt_path: Path) -> str:
    return load_prompt(prompt_path, "Function-analysis prompt")


def context_to_dict(context: FunctionAnalysisContext) -> dict:
    """Serialize only already-bounded context for one function as plain JSON data."""
    return {
        "function": {
            "address": "0x{0:X}".format(context.function.address),
            "name": context.function.name,
            "size": context.function.size,
            "signature": context.function.signature,
        },
        "pseudocode": context.pseudocode,
        "assembly": [{"address": "0x{0:X}".format(item.address), "text": item.text} for item in context.assembly],
        "callers": [{"address": "0x{0:X}".format(item.address), "name": item.name} for item in context.callers],
        "callees": [{"address": "0x{0:X}".format(item.address), "name": item.name} for item in context.callees],
        "referenced_imports_or_globals": [
            {"address": "0x{0:X}".format(item.address), "name": item.name} for item in context.referenced_names
        ],
        "strings": list(context.strings),
        "basic_blocks": [
            {"start": "0x{0:X}".format(item.start_address), "end": "0x{0:X}".format(item.end_address)}
            for item in context.basic_blocks
        ],
        "truncated_sections": list(context.truncated_sections),
    }


def build_function_request(
    context: FunctionAnalysisContext,
    system_prompt: str,
    max_output_tokens: int = 2048,
    temperature: float = 0.2,
) -> LLMRequest:
    """Build the single-shot analysis request from bounded function context."""
    payload = context_to_dict(context)
    return LLMRequest(
        prompt="Analyze only this selected-function context. Return the required JSON object.\n\n"
        + json.dumps(payload, ensure_ascii=False),
        system_instruction=system_prompt,
        max_output_tokens=max_output_tokens,
        temperature=temperature,
        response_mime_type="application/json",
    )


def analyze_function_context(context: FunctionAnalysisContext, provider: LLMProvider, system_prompt: str) -> FunctionAnalysis:
    return parse_function_analysis(provider.generate(build_function_request(context, system_prompt)).text)


def parse_function_analysis(raw: str) -> FunctionAnalysis:
    """Safely recover a fenced JSON object, then validate every display field."""
    if not isinstance(raw, str) or not raw.strip():
        raise AnalysisResponseError("The model returned an empty analysis")
    candidate = strip_json_fence(raw)
    try:
        value = json.loads(candidate)
    except json.JSONDecodeError as exc:
        raise AnalysisResponseError("The model returned malformed analysis JSON") from exc
    if not isinstance(value, dict):
        raise AnalysisResponseError("The model analysis must be a JSON object")
    required = {
        "summary", "observed_behavior", "inferences", "hypotheses", "important_apis", "important_strings",
        "related_functions", "evidence", "confidence", "uncertainties", "suggested_name",
    }
    if set(value) != required:
        raise AnalysisResponseError("The model analysis did not match the required schema")
    confidence = value["confidence"]
    if not isinstance(confidence, dict) or set(confidence) != {"behavior"} or not isinstance(confidence["behavior"], (int, float)):
        raise AnalysisResponseError("The model analysis confidence is invalid")
    behavior_confidence = float(confidence["behavior"])
    if not 0.0 <= behavior_confidence <= 1.0:
        raise AnalysisResponseError("The model analysis confidence is outside the valid range")
    suggested_name = value["suggested_name"]
    if suggested_name is not None and (not isinstance(suggested_name, str) or not suggested_name.strip()):
        raise AnalysisResponseError("The suggested name is invalid")
    return FunctionAnalysis(
        summary=_required_text(value, "summary"),
        observed_behavior=_string_list(value, "observed_behavior"),
        inferences=_string_list(value, "inferences"),
        hypotheses=_string_list(value, "hypotheses"),
        important_apis=_string_list(value, "important_apis"),
        important_strings=_string_list(value, "important_strings"),
        related_functions=_string_list(value, "related_functions"),
        evidence=_string_list(value, "evidence"),
        behavior_confidence=behavior_confidence,
        uncertainties=_string_list(value, "uncertainties"),
        suggested_name=suggested_name.strip() if suggested_name else None,
    )


def _required_text(value: Mapping[str, Any], name: str) -> str:
    item = value[name]
    if not isinstance(item, str) or not item.strip():
        raise AnalysisResponseError("{0} must be a non-empty string".format(name))
    return item.strip()


def _string_list(value: Mapping[str, Any], name: str) -> Tuple[str, ...]:
    items = value[name]
    if not isinstance(items, list) or any(not isinstance(item, str) or not item.strip() for item in items):
        raise AnalysisResponseError("{0} must be a list of non-empty strings".format(name))
    return tuple(item.strip() for item in items)

