    def __post_init__(self) -> None:
        if self.category not in CATEGORIES:
            raise ValueError("unknown capability category: {0}".format(self.category))
        if self.basis not in BASES:
            raise ValueError("unknown finding basis: {0}".format(self.basis))
        if not isinstance(self.confidence, (int, float)) or not 0.0 <= float(self.confidence) <= 1.0:
            raise ValueError("confidence must be within 0..1")
        if self.mitre_technique is not None and not MITRE_TECHNIQUE_RE.match(self.mitre_technique):
            raise ValueError("invalid MITRE technique id: {0}".format(self.mitre_technique))

    @property
    def confidence_label(self) -> str:
        """AGENTS.md section 27 display label; avoids false precision."""
        if self.basis == "hypothesis":
            return "Investigate"
        if self.confidence >= 0.75:
            return "High"
        if self.confidence >= 0.45:
            return "Medium"
        return "Low"


