def context_api_names(context: FunctionAnalysisContext) -> Tuple[str, ...]:
    """Raw API-like names visible in the context: referenced names, callees, call targets in assembly."""
    names: List[str] = []
    for item in context.referenced_names:
        names.append(item.name)
    for item in context.callees:
        names.append(item.name)
    for instruction in context.assembly:
        text = instruction.text
        if "call" in text or "jmp" in text:
            for token in re.findall(r"[A-Za-z_][A-Za-z0-9_@.!]*", text):
                if lookup_api(token) is not None:
                    names.append(token)
    ordered: List[str] = []
    seen: Set[str] = set()
    for name in names:
        if name and name not in seen:
            seen.add(name)
            ordered.append(name)
    return tuple(ordered)


def local_capability_signals(context: FunctionAnalysisContext) -> Tuple[LocalCapabilitySignal, ...]:
    """Run the deterministic catalogue over the context. No AI, no IDA access."""
    apis = context_api_names(context)
    return tuple(detect_combinations(apis, context.strings))


