def functions(self, kinds: Optional[Iterable[str]] = None) -> Tuple[FunctionRecord, ...]:
    kind_list = list(kinds or ())
    if kind_list:
        marks = ",".join("?" for _ in kind_list)
        rows = self._execute(
            "SELECT address, kind, name, origin, summary, payload, fingerprint, updated_at FROM functions"
            " WHERE binary_id = ? AND kind IN ({0}) ORDER BY address".format(marks),
            [self.binary_id] + kind_list,
        )
    else:
        rows = self._execute(
            "SELECT address, kind, name, origin, summary, payload, fingerprint, updated_at FROM functions"
            " WHERE binary_id = ? ORDER BY address",
            (self.binary_id,),
        )
    return tuple(_record(row) for row in rows)

def function(self, address: int, kinds: Iterable[str] = ()) -> Tuple[FunctionRecord, ...]:
    return tuple(item for item in self.functions(kinds) if item.address == address)

def parse_capability_report(
    raw: str, context: FunctionAnalysisContext, signals: Sequence[LocalCapabilitySignal]
) -> CapabilityReport:
    """Strictly validate the model JSON and enforce every evidence rule.

    Structural violations (bad JSON, wrong keys, bad category, bad basis, bad
    MITRE id, out-of-range confidence, observed finding without evidence)
    raise :class:`CapabilityResponseError`. Semantic violations that can be
    made safe (an API the context does not contain, an out-of-range evidence
    address) downgrade the finding to ``hypothesis`` and add an uncertainty so
    nothing is accepted silently.
    """
    if not isinstance(raw, str) or not raw.strip():
        raise CapabilityResponseError("The model returned an empty capability report")
    try:
        value = json.loads(strip_json_fence(raw))
    except json.JSONDecodeError as exc:
        raise CapabilityResponseError("The model returned malformed capability JSON") from exc
    if not isinstance(value, dict):
        raise CapabilityResponseError("The capability report must be a JSON object")
    if set(value) != _REQUIRED_TOP:
        raise CapabilityResponseError("The capability report did not match the required schema")
    summary = _required_text(value, "summary")
    uncertainties = list(_string_list(value, "uncertainties"))
    raw_findings = value["findings"]
    if not isinstance(raw_findings, list):
        raise CapabilityResponseError("findings must be a list")
    if len(raw_findings) > MAX_FINDINGS:
        raise CapabilityResponseError("too many findings")

    known_tokens = _known_api_tokens(context)
    known_canonical = {canonical_api_name(token) for token in known_tokens}
    start, end, listed = _allowed_addresses(context)
    context_strings = set(context.strings)

    findings: List[CapabilityFinding] = []
    for index, item in enumerate(raw_findings):
        if not isinstance(item, dict) or set(item) != _REQUIRED_FINDING:
            raise CapabilityResponseError("finding {0} did not match the required schema".format(index))
        category = item["category"]
        if category not in CATEGORIES:
            raise CapabilityResponseError("finding {0} has an unknown category".format(index))
        basis = item["basis"]
        if basis not in BASES:
            raise CapabilityResponseError("finding {0} has an unknown basis".format(index))
        confidence = item["confidence"]
        if isinstance(confidence, bool) or not isinstance(confidence, (int, float)) or not 0.0 <= float(confidence) <= 1.0:
            raise CapabilityResponseError("finding {0} confidence is outside 0..1".format(index))
        mitre = item["mitre_technique"]
        if mitre is not None and (not isinstance(mitre, str) or not MITRE_TECHNIQUE_RE.match(mitre)):
            raise CapabilityResponseError("finding {0} has an invalid MITRE technique id".format(index))
        capability = _required_text(item, "capability")
        description = _required_text(item, "description")
        evidence = _string_list(item, "evidence")
        apis = _string_list(item, "apis")
        strings = _string_list(item, "strings")
        if basis == "observed" and not evidence:
            raise CapabilityResponseError(
                "finding {0} ({1}) is marked observed but has no evidence".format(index, capability)
            )

        downgrade_reasons: List[str] = []
        unknown_apis = [api for api in apis if api not in known_tokens and canonical_api_name(api) not in known_canonical]
        if unknown_apis:
            downgrade_reasons.append(
                "API(s) not present in the function context: {0}".format(", ".join(unknown_apis))
            )
        bad_addresses = [entry for entry in evidence if not _evidence_address_ok(entry, start, end, listed)]
        if bad_addresses:
            downgrade_reasons.append(
                "evidence address(es) outside the function or its references: {0}".format("; ".join(bad_addresses))
            )
        unknown_strings = [text for text in strings if text not in context_strings and not _string_in_context(text, context)]
        if unknown_strings:
            downgrade_reasons.append(
                "string(s) not present in the function context: {0}".format(", ".join(repr(s) for s in unknown_strings))
            )
        final_basis = basis
        final_confidence = float(confidence)
        if downgrade_reasons:
            final_basis = "hypothesis"
            final_confidence = min(final_confidence, 0.4)
            uncertainties.append(
                "Finding '{0}' downgraded to hypothesis: {1}.".format(capability, "; ".join(downgrade_reasons))
            )
        findings.append(
            CapabilityFinding(
                category=category,
                capability=capability,
                description=description,
                evidence=evidence,
                apis=apis,
                strings=strings,
                confidence=final_confidence,
                basis=final_basis,
                mitre_technique=mitre,
            )
        )

    return CapabilityReport(
        function_address=context.function.address,
        function_name=context.function.name,
        findings=tuple(findings),
        local_signals=tuple(signals),
        summary=summary,
        uncertainties=tuple(dict.fromkeys(uncertainties)),
    )


def _string_in_context(text: str, context: FunctionAnalysisContext) -> bool:
    """Accept a model string when it is a substring of a context string, pseudocode, or assembly."""
    lowered = text.lower()
    if any(lowered in item.lower() for item in context.strings):
        return True
    if context.pseudocode and lowered in context.pseudocode.lower():
        return True
    return any(lowered in instruction.text.lower() for instruction in context.assembly)


def _required_text(value: Mapping[str, Any], name: str) -> str:
    item = value.get(name)
    if not isinstance(item, str) or not item.strip():
        raise CapabilityResponseError("{0} must be a non-empty string".format(name))
    return item.strip()


def _string_list(value: Mapping[str, Any], name: str) -> Tuple[str, ...]:
    items = value.get(name)
    if not isinstance(items, list) or any(not isinstance(item, str) or not item.strip() for item in items):
        raise CapabilityResponseError("{0} must be a list of non-empty strings".format(name))
    if len(items) > MAX_LIST_ITEMS:
        raise CapabilityResponseError("{0} contains too many items".format(name))
    return tuple(item.strip() for item in items)


