def _signal_covered(signal: LocalCapabilitySignal, findings: Sequence[CapabilityFinding]) -> bool:
    """A signal is covered when a same-category finding mentions its label or most of its APIs."""
    signal_apis = {canonical_api_name(api) for api in signal.matched_apis}
    label = signal.label.lower()
    for finding in findings:
        if finding.category != signal.category:
            continue
        text = (finding.capability + " " + finding.description).lower()
        if label in text:
            return True
        if signal.mitre_technique and finding.mitre_technique == signal.mitre_technique:
            return True
        finding_apis = {canonical_api_name(api) for api in finding.apis}
        if signal_apis and len(signal_apis & finding_apis) * 2 >= len(signal_apis):
            return True
        if not signal_apis and signal.matched_strings and set(signal.matched_strings) & set(finding.strings):
            return True
    return False


def merge_local_and_model(signals: Sequence[LocalCapabilitySignal], report: CapabilityReport) -> CapabilityReport:
    """Append strong deterministic signals the model ignored as observed findings (confidence 0.6)."""
    findings = list(report.findings)
    uncertainties = list(report.uncertainties)
    for signal in signals:
        if strength_rank(signal.strength) < strength_rank("strong"):
            continue
        if _signal_covered(signal, findings):
            continue
        evidence = tuple("API: {0}".format(api) for api in signal.matched_apis) + tuple(
            "STRING: {0}".format(text) for text in signal.matched_strings
        )
        findings.append(
            CapabilityFinding(
                category=signal.category,
                capability=signal.label,
                description="Deterministic catalogue match ({0} signal) not addressed by the model; "
                "derived from APIs and strings present in the function context.".format(signal.strength),
                evidence=evidence,
                apis=signal.matched_apis,
                strings=signal.matched_strings,
                confidence=MERGED_LOCAL_CONFIDENCE,
                basis="observed",
                mitre_technique=signal.mitre_technique,
            )
        )
        uncertainties.append(
            "Local signal '{0}' was not confirmed or refuted by the model; added from the catalogue.".format(signal.label)
        )
    return replace(report, findings=tuple(findings), uncertainties=tuple(dict.fromkeys(uncertainties)))


