def format_capability_report(report: CapabilityReport) -> str:
    """Plain-text rendering for the dockable panel: one section per category."""
    lines: List[str] = []
    lines.append("Capability Analysis: {0} (0x{1:X})".format(report.function_name, report.function_address))
    lines.append("")
    lines.append("Summary")
    lines.append(report.summary)
    lines.append("")
    if not report.findings:
        lines.append("Findings")
        lines.append("No capability findings. Absence of a finding is not proof of absence.")
        lines.append("")
    for category in CATEGORIES:
        items = report.findings_for(category)
        if not items:
