            if finding.strings:
                lines.append("  Strings: {0}".format(", ".join(finding.strings)))
            for entry in finding.evidence:
                lines.append("  Evidence: {0}".format(entry))
        lines.append("")
    if report.local_signals:
        lines.append("Local Signals (deterministic, not conclusions)")
        for signal in report.local_signals:
            parts = list(signal.matched_apis) + list(signal.matched_strings)
            lines.append("- [{0}] {1} ({2}): {3}".format(signal.strength, signal.label, signal.category, ", ".join(parts)))
        lines.append("")
    lines.append("Uncertainties")
    if report.uncertainties:
        for item in report.uncertainties:
            lines.append("- {0}".format(item))
    else:
        lines.append("- None stated.")
    return "\n".join(lines).rstrip() + "\n"


